var DX_BODY = window.DX_BODY || {};

/* ==================== الشبكية وداخل العين ==================== */

DX_BODY['retinal-detachment'] = {
  symptoms: {
    ar: 'يبدأ الأمر بلا ألم إطلاقاً، وهذا ما يخدع الناس. أول ما يظهر ومضات ضوء خاطفة كالبرق في طرف مجال النظر تُرى أوضح في العتمة، ثم فيض مفاجئ من العوّامات: نقاط سوداء أو خيوط أو ما يشبه سرباً من الذباب ينهمر أمام العين دفعة واحدة. بعدها تظهر العلامة الحاسمة: ظلّ داكن أو ستارة تنزل من أعلى أو ترتفع من أسفل أو تزحف من الجانب فتقتطع جزءاً من المنظر، ولا تزول بفرك العين ولا بالرمش ولا بتغيير الإضاءة. وكلما اتسع الانفصال ضاق المشهد حتى يبلغ مركز الإبصار فيسقط وضوح الرؤية كله. والإصابة في عين واحدة عادةً، فقد لا ينتبه صاحبها إلا حين يغمض العين السليمة مصادفةً.',
    en: 'It begins with no pain at all, and that is what deceives people. First come brief flashes of light like lightning at the edge of the field of view, clearer in the dark, then a sudden shower of floaters: black dots, threads or what looks like a swarm of flies pouring in at once. Then comes the decisive sign: a dark shadow or curtain descending from above, rising from below or creeping in from the side, cutting away part of the scene, and it does not clear with rubbing, blinking or changing the light. As the detachment spreads the picture narrows until it reaches the centre of vision and all sharpness collapses. It usually strikes one eye, so the person may notice nothing until he happens to close the good one.'
  },
  cause: {
    ar: 'الشبكية طبقة رقيقة كورق مبتلّ ملتصقة بجدار العين من الداخل، ويملأ التجويف أمامها هلام شفاف. مع العمر ينكمش هذا الهلام وينسحب عنها، وقد يشدّها عند نقطة ضعيفة فيُحدث فيها تمزّقاً صغيراً، فيتسرّب السائل من خلف التمزّق ويرفع الطبقة عن جدارها كورق جدران يتقشّر بالماء. وأكبر عوامل الخطر قصر النظر الشديد لأن المقلة فيه أطول والشبكية أرقّ، ثم السنّ بين الخمسين والسبعين، وعملية الساد السابقة، وضربة على العين أو الرأس، ووجود انفصال سابق في العين الأخرى أو في العائلة. وهناك نوع آخر يجرّ فيه نسيج ليفي الشبكية عند مرضى السكري المتقدّم، ونوع ثالث يرفعها فيه سائل التهابي أو ورمي.',
    en: 'The retina is a layer as thin as wet paper, laid against the inner wall of the eye, with a clear gel filling the cavity in front of it. With age this gel shrinks and pulls away, and it may tug on a weak point and make a small tear; fluid then seeps behind the tear and lifts the layer off its wall like wallpaper peeling with water. The biggest risk factor is severe short-sightedness, because the eyeball is longer and the retina thinner, then age between fifty and seventy, previous cataract surgery, a blow to the eye or head, and a previous detachment in the other eye or in the family. Another type occurs when fibrous tissue drags the retina in advanced diabetes, and a third when inflammatory or tumour fluid lifts it.'
  },
  diagnosis: {
    ar: 'التشخيص يُعمل بالعين المتّسعة لا بغيرها: تُقطَّر قطرة توسّع البؤبؤ، ثم يفحص طبيب العيون قاع العين بمنظار غير مباشر مع ضغط لطيف على محيط المقلة ليرى الأطراف البعيدة حيث تبدأ أكثر التمزّقات، وهذا الفحص وحده هو ما يفرّق بين عوّامات سليمة وتمزّق يهدّد البصر. ويُكمَل بفحص المصباح الشقّي بعدسة خاصة لتحديد موضع التمزّق وعدده وشكله بدقّة لأن ذلك يقرّر نوع العملية. وإن كان داخل العين نزيف يحجب الرؤية استُعين بالموجات الصوتية على العين، فهي تُظهر الشبكية مرفوعة حتى من خلف الدم. ويُقاس البصر وضغط العين ويُفحص مجال الرؤية ليُعرف كم من الشبكية سقط وهل بلغ المركز.',
    en: 'The diagnosis is made through a dilated pupil and no other way: drops widen the pupil, then the ophthalmologist examines the back of the eye with an indirect scope while gently pressing around the globe to see the far periphery where most tears begin, and this examination alone separates harmless floaters from a sight-threatening tear. It is completed with a slit lamp and a special lens to fix the position, number and shape of the tear precisely, because that decides which operation is needed. If bleeding inside the eye blocks the view, ultrasound of the eye is used, since it shows the lifted retina even from behind the blood. Vision and eye pressure are measured and the visual field checked, to learn how much retina has come down and whether it has reached the centre.'
  },
  treatment: {
    ar: 'عملية لا تحتمل التأجيل، ونوعها يقرّره الجرّاح حسب موضع التمزّق واتساع الانفصال. إن كان الأمر تمزّقاً بلا انفصال بعد، فقد يكفي إحكامه بالليزر أو بالتجميد في العيادة فيلتحم حوله نسيج يمنع تسرّب السائل. وإن انفصلت الشبكية فعلاً فالخيارات ثلاثة: حقن فقاعة غاز داخل العين تدفع الطبقة إلى مكانها ويلتزم المريض بوضعية رأس معيّنة أياماً حتى تلتحم، أو خياطة شريط رقيق حول المقلة يقرّب جدارها من الشبكية، أو استئصال الهلام من داخل العين وتسطيح الشبكية ثم ملء التجويف بغاز أو زيت. والنتيجة تتعلّق بشيء واحد قبل مهارة الجرّاح: هل وصل الانفصال إلى مركز الإبصار أم لا، فما قبل وصوله يُنقذ غالباً وما بعده يبقى منه نقص دائم. ومن وُضعت في عينه فقاعة غاز يُمنع من السفر جواً حتى تذوب، ويُمنع كذلك من الغوص وصعود المرتفعات، وعليه أن يخبر أي طبيب أو طبيب أسنان بوجود الفقاعة قبل أي تخدير، لأن غاز أكسيد النيتروز المستعمل في التخدير يتمدّد داخلها فيرفع ضغط العين ارتفاعاً مؤذياً.',
    en: 'An operation that cannot be postponed, and the surgeon chooses its type by the position of the tear and the extent of the detachment. If there is a tear but no detachment yet, sealing it with laser or freezing in the clinic may be enough, so scar tissue forms around it and stops fluid seeping through. If the retina has truly come away there are three options: injecting a gas bubble inside the eye that pushes the layer back while the patient holds a set head position for days until it heals; stitching a thin band around the globe to bring its wall closer to the retina; or removing the gel from inside the eye, flattening the retina and filling the cavity with gas or oil. The outcome hangs on one thing even before the surgeon skill: whether the detachment reached the centre of vision, since before that sight is usually saved and after it some loss remains. Anyone with a gas bubble must not fly until it dissolves, nor dive or go up to altitude, and must tell any doctor or dentist that the bubble is there before any anaesthetic, because the nitrous oxide used in anaesthesia expands inside it and drives the eye pressure up harmfully.'
  },
  seeDoctor: {
    ar: 'اذهب إلى طوارئ العيون في اليوم نفسه، لا بعد أيام ولا بعد نهاية الأسبوع، إذا رأيت ومضات ضوء جديدة، أو انهمر أمامك سيل مفاجئ من العوّامات، أو أحسست بظلّ أو ستارة تقتطع جزءاً من مجال نظرك، أو هبط بصرك في عين واحدة بغتة. ولا تنتظر أن يؤلمك شيء فهذه حالة صامتة بلا ألم. ولا تطمئنّ لأن العين الأخرى ترى جيداً، فالدماغ يغطّي النقص فلا تلاحظه إلا بغمض السليمة. وإن كنت قصير نظر شديداً أو أُجريت لك عملية ساد أو أُصبت بضربة على العين فاعتبر هذه العلامات إنذاراً لك أنت بالذات. أما إن كنت تعايش عوّامات قديمة ثابتة منذ سنين لم يتغيّر شكلها ولا عددها فاذكرها في فحصك السنوي ولا تفزع منها.',
    en: 'Go to an eye emergency department the same day, not in a few days and not after the weekend, if you see new flashes of light, a sudden shower of floaters, a shadow or curtain cutting into your field of view, or a sudden drop of vision in one eye. Do not wait for pain, because this condition is silent. Do not be reassured because the other eye sees well, since the brain covers the gap and you may only notice it by closing the good eye. If you are severely short-sighted, have had cataract surgery or took a blow to the eye, treat these signs as a warning meant for you in particular. If instead you have lived for years with old, unchanging floaters of the same shape and number, mention them at your yearly check and do not be alarmed.'
  },
  updated: '2026-09-08'
};

DX_BODY['retinal-vascular-occlusion'] = {
  symptoms: {
    ar: 'فقدان بصر مفاجئ بلا ألم في عين واحدة هو العنوان. في انسداد الشريان يحدث ذلك في ثوانٍ: يظلم المشهد كله أو يسقط نصفه العلوي أو السفلي كأن ستاراً هبط، وقد يسبقه في الأيام السابقة عمى عابر يدوم دقائق ثم يرجع البصر — وهذه من أخطر إشارات الإنذار لأنها تنذر بسكتة دماغية وشيكة. أما انسداد الوريد فأبطأ وأرحم: يستيقظ الإنسان فيجد بصره ضبابياً أو مشوّشاً في عين واحدة، أو يرى بقعة ثابتة معتمة في المنتصف، ويزداد التشوّش خلال أيام. وفي الحالتين لا احمرار ولا إفراز ولا ألم، ولهذا يؤجّل كثيرون الذهاب ظنّاً أنها إجهاد أو ارتفاع ضغط عابر أو ماء نزل على العين.',
    en: 'Sudden painless loss of vision in one eye is the headline. With an artery blockage it happens in seconds: the whole scene goes dark, or its upper or lower half drops away as though a curtain had fallen, and in the preceding days there may have been a passing blindness lasting minutes before sight returned, which is among the most serious warning signs of all because it announces an imminent stroke. A vein blockage is slower and kinder: the person wakes to find the vision of one eye hazy or scrambled, or sees a fixed dark patch in the middle, and the blurring increases over days. In both there is no redness, no discharge and no pain, which is why many delay, assuming it is strain or a passing rise in pressure.'
  },
  cause: {
    ar: 'شرايين الشبكية وأوردتها من أدقّ أوعية الجسم، ويمرّ الشريان والوريد معاً في نفق ضيّق داخل العصب البصري. فإذا تصلّب الشريان وتيبّس جداره ضغط على الوريد المجاور فتباطأ الدم فيه حتى يتخثّر، وهذا أصل انسداد الوريد. أما الشريان فيسدّه غالباً جسم صغير طائر قادم من مكان أبعد: من لويحة متقشّرة في شريان الرقبة أو من جلطة في قلب يرجف، فيستقرّ في وعاء الشبكية ويقطع عنها الدم. ولهذا فالحالة ليست مرض عين بل مرض شرايين ظهر في العين. وعوامل الخطر هي نفسها: ارتفاع ضغط الدم وهو الأول، ثم السكري وارتفاع الكوليسترول والتدخين والسنّ المتقدّم والرجفان الأذيني وارتفاع ضغط العين وأمراض تخثّر الدم. وعند الشباب يُبحث عن التهاب أوعية أو ميل وراثي للتخثّر.',
    en: 'The retinal arteries and veins are among the finest vessels in the body, and the artery and vein pass together through a narrow tunnel inside the optic nerve. If the artery hardens, its stiff wall presses on the neighbouring vein until the blood slows and clots, and that is the origin of vein occlusion. The artery, by contrast, is usually blocked by a small travelling fragment from further away: from a cracked plaque in the neck artery or a clot in a fibrillating heart, which lodges in a retinal vessel and cuts off the blood. So this is not an eye disease but an arterial disease that has appeared in the eye. The risk factors are the same: high blood pressure first, then diabetes, high cholesterol, smoking, older age, atrial fibrillation, raised eye pressure and clotting disorders. In young patients, vessel inflammation or an inherited clotting tendency is sought.'
  },
  diagnosis: {
    ar: 'يُوسَّع البؤبؤ ويُفحص قاع العين، فمنظره وحده يكاد يحسم الأمر: شبكية شاحبة كاللبن مع بقعة حمراء في المركز تعني انسداد شريان، ونزوف منتشرة كألسنة لهب مع أوردة متعرّجة منتفخة تعني انسداد وريد. ثم يُصوَّر المركز بالتصوير المقطعي البصري ليُقاس التورّم الذي يهبط البصر، وقد يُحقن صبغ في الوريد وتُصوَّر الأوعية لمعرفة أي مناطق حُرمت الدم تماماً، لأن هذي المناطق هي التي تولّد لاحقاً أوعية جديدة هشّة تنزف وترفع ضغط العين. والأهمّ أن الفحص لا يقف عند العين: يُقاس ضغط الدم ويُسحب دم للسكر والدهون، ويُصوَّر شريان الرقبة بالموجات الصوتية، ويُسجَّل نظم القلب بحثاً عن رجفان أذيني. وعند من تجاوز الخمسين تُطلب تحاليل الالتهاب فوراً لاستبعاد التهاب الشرايين الصدغي لأنه قد يُعمي العين الأخرى خلال أيام إن أُهمل.',
    en: 'The pupil is dilated and the back of the eye examined, and its appearance alone nearly settles the matter: a milky pale retina with a red spot at the centre means an artery blockage, while scattered flame-shaped haemorrhages with swollen tortuous veins mean a vein blockage. The centre is then imaged with optical coherence tomography to measure the swelling that lowers vision, and dye may be injected into a vein to photograph the vessels and find which areas have been left without blood, since those are the areas that later grow fragile new vessels that bleed and raise eye pressure. Most important, the work-up does not stop at the eye: blood pressure is measured, blood taken for sugar and lipids, the neck artery scanned by ultrasound and the heart rhythm recorded to look for atrial fibrillation. Over the age of fifty, inflammatory blood tests are requested at once to exclude temporal arteritis, which can blind the other eye within days if missed.'
  },
  treatment: {
    ar: 'انسداد الشريان سباق مع الوقت لا يُنتظر فيه شيء: تُنقل الحالة إلى مستشفى فيه وحدة سكتات كما تُنقل جلطة الدماغ تماماً، لأن نصف الأمر إنقاذ ما بقي من بصر ونصفه الآخر منع سكتة دماغية في الأيام التالية. وما كان يُجرَّب قديماً من تدليك العين أو سحب قطرة من سائل مقدّمتها لدفع الجسم الساد إلى فرع أضيق لم يعد علاجاً معتمداً، فدليله ضعيف غير حاسم وللسحب مضاعفاته. والإجراء الوحيد المرتبط بساعة هو إذابة الجلطة وريدياً خلال أربع ساعات ونصف من أول لحظة فقدان البصر لمن لا مانع طبّياً عنده، ولهذا تُنقل الحالة في دقائقها إلى مستشفى يقدر عليه. والنتائج تبقى متواضعة ويُصارَح بها المريض. أما انسداد الوريد فعلاجه أطول وأجدى: حقن داخل العين يكرّره الطبيب بفواصل ليجفّف تورّم مركز الإبصار فيتحسّن الوضوح، وليزر على المناطق المحرومة من الدم لمنع نمو الأوعية الهشّة ومنع الزرق. وفي الحالتين لا يكتمل العلاج إلا بضبط الضغط والسكر والدهون وترك التدخين وعلاج ما يُكتشف في شريان الرقبة أو في نظم القلب، فالعين الأخرى معرّضة لما أصاب أختها.',
    en: 'An artery blockage is a race against time in which nothing is waited for: the patient is taken to a hospital with a stroke unit exactly as a brain clot would be, because half the task is saving what sight remains and the other half is preventing a stroke in the days that follow. The old attempts at ocular massage, or drawing a drop of fluid from the front of the eye to push the blocking fragment into a narrower branch, are no longer standard treatment: the evidence for them is weak and inconclusive and the drainage carries its own complications. The only step tied to a clock is intravenous clot dissolution within four and a half hours of the first moment of visual loss in anyone with no medical contraindication, which is why the patient is moved within minutes to a hospital able to give it. The results remain modest and are stated plainly to the patient. A vein blockage is treated longer and to better effect: injections inside the eye, repeated at intervals decided by the doctor, dry the swelling at the centre of vision so clarity improves, and laser to the blood-starved areas prevents fragile new vessels and glaucoma. In both, treatment is incomplete without controlling blood pressure, sugar and lipids, stopping smoking and treating whatever is found in the neck artery or the heart rhythm, because the other eye is exposed to what struck its twin.'
  },
  seeDoctor: {
    ar: 'اتصل بالإسعاف أو اذهب إلى الطوارئ في الحال — لا موعد عيادة ولا انتظار صباح الغد — إذا فقدت البصر أو جزءاً منه في عين واحدة فجأةً وبلا ألم. وهذا ينطبق حتى لو رجع البصر بعد دقائق، فالعمى العابر إنذار سكتة ومن يتجاهله يخسر أكثر من عينه. اطلب الطوارئ أيضاً إن صحب فقدان البصر ضعف في جهة من الجسم أو تلعثم في الكلام أو ميل في الوجه. وإن كنت فوق الخمسين وجاءك مع فقدان البصر صداع في الصدغ أو ألم في الفكّ عند المضغ أو إرهاق وحمّى فقل ذلك لطبيب الطوارئ صراحةً، فهي حالة تُعالج في ساعتها. وراجع طبيب العيون خلال أيام إن ظهرت بقعة معتمة ثابتة في وسط النظر أو ضبابية جديدة في عين واحدة تزداد ببطء.',
    en: 'Call an ambulance or go to the emergency department at once — not a clinic appointment, not tomorrow morning — if you lose vision or part of it in one eye suddenly and painlessly. This holds even if the sight came back after minutes, because passing blindness warns of a stroke and whoever ignores it loses more than an eye. Seek emergency care too if the visual loss comes with weakness on one side, slurred speech or a drooping face. If you are over fifty and the visual loss comes with pain in the temple, jaw pain on chewing, or fatigue and fever, say so plainly to the emergency doctor, because that condition is treated within the hour. See an ophthalmologist within days if a fixed dark patch appears in the middle of your vision, or new blurring in one eye slowly increases.'
  },
  updated: '2026-09-08'
};

DX_BODY['uveitis'] = {
  symptoms: {
    ar: 'عين واحدة تحمرّ حمرة عميقة تتركّز في الحلقة الملاصقة للقرنية لا في بياض العين كله، ويصحبها ألم غائر وحساسية شديدة للضوء تجعل صاحبها يُغمض في النور، حتى إنه يتوجّع إذا سُلّط الضوء على العين الأخرى. الرؤية تضبّب وتظهر عوّامات، والدمع قليل بلا صديد ولا التصاق للجفون عند الصباح، وهذا أهمّ ما يفرّقها عن الرمد المعدي الذي يبدأ بإفراز لزج ولا يؤلم هذا الألم. والبؤبؤ قد يبدو أصغر وغير مستدير تماماً. وهناك صورة أخرى بطيئة تصيب الجزء الخلفي فلا تحمرّ فيها العين ولا تؤلم، وكل ما يشكوه صاحبها عوّامات كثيرة وضبابية تزداد شهراً بعد شهر. وعند الأطفال المصابين بالتهاب مفاصل قد لا يظهر شيء إطلاقاً حتى يُكتشف الضرر متأخراً.',
    en: 'One eye reddens deeply in the ring next to the cornea rather than across the whole white, with a deep ache and such sensitivity to light that the person shuts his eye in daylight and even hurts when light is shone into the other eye. Vision blurs and floaters appear, while tearing is slight, with no pus and no lids stuck together in the morning, and that is the main thing separating it from infectious conjunctivitis, which begins with sticky discharge and does not ache like this. The pupil may look smaller and not quite round. There is also a slow form affecting the back of the eye in which the eye is neither red nor painful, and all the person reports is many floaters and blurring that worsens month by month. In children with joint inflammation nothing may show at all until damage is found late.'
  },
  cause: {
    ar: 'العنبية طبقة وسطى مليئة بالأوعية تغذّي داخل العين، فإذا التهبت تسرّبت الخلايا الالتهابية إلى سائل العين. وفي نحو نصف الحالات لا يُعرف سبب ويبقى الالتهاب معزولاً في العين وحدها. أما البقية فوراءها غالباً مرض مناعي في الجسم كله: التهاب الفقار اللاصق، والتهاب المفاصل عند الأطفال، وداء بهجت، والساركويد، وأمراض الأمعاء الالتهابية. وقد تكون العلّة عدوى: السلّ والزهري وداء المقوّسات وفيروسات الهربس والحزام الناري، وهذا فرق حاسم لأن علاج العدوى عكس علاج فرط المناعة تماماً. وتأتي أيضاً بعد رضّ على العين أو بعد عملية أو مع وجود جسم غريب داخلها. وقد يرتبط بعضها باستعداد وراثي معروف يمكن كشفه بتحليل دم.',
    en: 'The uvea is the middle, vessel-rich layer that nourishes the inside of the eye, and when it becomes inflamed, inflammatory cells leak into the fluid of the eye. In about half the cases no cause is found and the inflammation stays confined to the eye. Behind most of the rest lies an immune disease of the whole body: ankylosing spondylitis, childhood arthritis, Behcet disease, sarcoidosis and inflammatory bowel disease. The cause may instead be an infection: tuberculosis, syphilis, toxoplasmosis, herpes viruses and shingles, and this distinction is decisive, because treating infection is the exact opposite of damping down immunity. It also follows a blow to the eye, surgery, or a retained foreign body. Some forms are linked to a known inherited predisposition detectable by a blood test.'
  },
  diagnosis: {
    ar: 'العمود الأول فحص المصباح الشقّي: يرى الطبيب خلايا التهابية تسبح في السائل أمام القزحية فيعدّها ويصنّف شدّتها، ويرى ترسّبات على ظهر القرنية والتصاقات بين القزحية والعدسة، وهذا وحده يميّز التهاب العنبية عن كل عين حمراء أخرى. ثم يُقاس ضغط العين لأنه قد يرتفع أو ينخفض في هذه الحالة وكلاهما مهمّ، ويُوسَّع البؤبؤ لفحص الجزء الخلفي والشبكية وتورّم مركز الإبصار. ويُصوَّر المركز بالتصوير المقطعي البصري إن ضعف البصر، وقد يُحقن صبغ لتصوير الأوعية. وبعد ذلك يبحث الطبيب عن سبب في الجسم لا في العين: تحاليل التهاب وأشعة صدر لاستبعاد السلّ والساركويد، وفحوص للزهري والهربس، وتحليل مناعي وراثي، وسؤال دقيق عن آلام الظهر وتقرّحات الفم والطفح الجلدي واضطراب الأمعاء.',
    en: 'The first pillar is the slit-lamp examination: the doctor sees inflammatory cells floating in the fluid in front of the iris, counts them and grades their severity, sees deposits on the back of the cornea and adhesions between the iris and the lens, and this alone separates uveitis from every other red eye. Eye pressure is then measured, since it may rise or fall here and both matter, and the pupil is dilated to examine the back of the eye, the retina and any swelling at the centre of vision. That centre is imaged by optical coherence tomography if sight is reduced, and dye may be injected to photograph the vessels. After that the doctor looks for a cause in the body rather than the eye: inflammatory blood tests and a chest x-ray to exclude tuberculosis and sarcoidosis, tests for syphilis and herpes, an immune-genetic test, and careful questions about back pain, mouth ulcers, rashes and bowel upset.'
  },
  treatment: {
    ar: 'الهدف إطفاء الالتهاب بسرعة قبل أن يترك أثراً دائماً، ثم منع رجوعه. يبدأ الطبيب بقطرات مضادّة للالتهاب بفواصل متقاربة في البداية ثم يخفّضها تدريجياً على أسابيع، ولا تُقطع فجأةً لأن الالتهاب يشتعل من جديد. ويضيف قطرة توسّع البؤبؤ لتريح العضلة المتشنّجة فيخفّ الألم وتُمنع الالتصاقات بين القزحية والعدسة. وإن كان الالتهاب في عمق العين أو شديداً فقد يُحقن الدواء حول العين أو داخلها أو يُعطى عن طريق الفم. وإن تكرّر أو ارتبط بمرض مناعي في الجسم انتقل العلاج إلى أدوية تكبح المناعة يشرف عليها طبيب روماتيزم مع طبيب العيون بتحاليل دورية. وإن ثبتت عدوى فالعلاج يستهدفها أولاً. وتبقى متابعة ضغط العين وعتامة العدسة ضرورة، لأن كليهما من مضاعفات المرض ومن علاجه معاً.',
    en: 'The aim is to put the inflammation out quickly before it leaves permanent marks, then to keep it from returning. The doctor starts with anti-inflammatory drops at close intervals, then tapers them over weeks; they are never stopped abruptly, because the inflammation flares again. A pupil-dilating drop is added to rest the cramped muscle, so the pain eases and adhesions between iris and lens are prevented. If the inflammation lies deep in the eye or is severe, the medicine may be injected around or inside the eye, or given by mouth. If it recurs or belongs to an immune disease of the body, treatment moves to medicines that damp the immune system, supervised jointly by a rheumatologist and an ophthalmologist with regular blood tests. If an infection is proven, treatment targets that first. Monitoring eye pressure and lens clouding remains essential, since both are complications of the disease and of its treatment alike.'
  },
  seeDoctor: {
    ar: 'اذهب إلى طبيب عيون في اليوم نفسه إذا احمرّت عين واحدة حمرة تحيط بالقرنية مع ألم غائر وحساسية للضوء وضبابية، خصوصاً إن كانت بلا إفراز صديدي. ولا تعالجها بقطرة تُذهب الاحمرار من الصيدلية ولا بقطرة كورتيزون قديمة بقيت من وصفة سابقة، فالقطرة الخاطئة على عدوى في القرنية قد تُعمي. اطلب الطوارئ فوراً إن هبط البصر بسرعة، أو اشتدّ الألم حتى منع النوم، أو صحبه غثيان وقيء وهالات حول الأضواء فقد يكون ضغط العين ارتفع. وراجع خلال أيام إن ظهرت عوّامات كثيرة جديدة أو ضبابية تزداد في عين واحدة بلا احمرار. ومن عنده مرض مناعي معروف، أو طفل مصاب بالتهاب مفاصل، فالفحص الدوري للعين ضرورة حتى بلا أي شكوى، لأن هذا النوع يتقدّم صامتاً.',
    en: 'See an ophthalmologist the same day if one eye reddens in a ring around the cornea with a deep ache, light sensitivity and blurring, especially with no pus. Do not treat it with a pharmacy redness-removing drop or an old steroid drop left from a previous prescription, because the wrong drop on a corneal infection can blind. Seek emergency care at once if vision drops quickly, if the pain becomes severe enough to prevent sleep, or if it comes with nausea, vomiting and haloes around lights, since eye pressure may have risen. Attend within days if many new floaters appear, or blurring increases in one eye without redness. Anyone with a known immune disease, or a child with joint inflammation, needs regular eye checks even with no complaint at all, because this form advances in silence.'
  },
  updated: '2026-09-08'
};

DX_BODY['keratitis'] = {
  symptoms: {
    ar: 'ألم حادّ في عين واحدة يوصف بأن شيئاً خشناً عالق تحت الجفن، ويزداد مع كل رمشة. تدمع العين بغزارة وتحمرّ حمرة شديدة حول القرنية، ولا يحتمل صاحبها الضوء حتى ضوء الغرفة، فيغطّي عينه ويرفض فتحها. الرؤية تضبّب وتبدو الأضواء ذات هالات. وقد تُرى في المرآة نقطة أو بقعة بيضاء رمادية على سواد العين، وهذه علامة قرحة لا تحتمل التأجيل ساعة واحدة. والقصة غالباً واضحة: لابس عدسة لاصقة نام بها أو غسلها بماء الصنبور، أو عامل دخلت عينه شظية أو رمل، أو من خُدشت عينه بظفر أو بحافة ورقة. وفي التهاب الهربس تتكرّر النوبة في العين نفسها ويقلّ الإحساس فيها، فيبدو الألم أخفّ مما يوحي به منظر القرنية.',
    en: 'Sharp pain in one eye, described as something rough caught under the lid, worsening with every blink. The eye waters heavily and reddens intensely around the cornea, and the person cannot bear light, even room light, so he covers the eye and refuses to open it. Vision blurs and lights acquire haloes. In the mirror a white-grey dot or patch may be visible on the dark part of the eye, and that is the sign of an ulcer that cannot wait a single hour. The story is usually clear: a contact lens wearer who slept in the lenses or rinsed them under the tap, a worker whose eye took a splinter or sand, or someone scratched by a fingernail or the edge of a page. In herpes keratitis the attack recurs in the same eye and sensation there is reduced, so the pain seems milder than the look of the cornea suggests.'
  },
  cause: {
    ar: 'القرنية طبقة شفافة بلا أوعية دموية، لا يحميها إلا الدمع والغشاء السطحي الرقيق. فإذا انخدش هذا الغشاء دخلت الجراثيم إلى نسيج لا تصله المناعة سريعاً، فتنتشر وتحفر قرحة خلال ساعات. وأكبر سبب في زماننا العدسات اللاصقة: النوم بها، وتجاوز مدّتها، وغسلها أو حفظها بالماء بدل المحلول، والسباحة والاستحمام بها. ثم إصابات العمل والزراعة، وبالأخصّ ما جرح العين بمادة نباتية فتلك بوابة الفطريات. ويضعف دفاع القرنية أيضاً في جفاف العين الشديد، وفي شلل الجفن الذي يمنع إغلاقه فتجفّ العين ليلاً، وعند مرضى السكري، وعند من يستعمل قطرة كورتيزون بلا إشراف. وهناك التهاب فيروسي بالهربس يسكن العصب ويعاود بشكل متفرّع مميّز، وطفيلي نادر شديد الخطورة مصدره الماء.',
    en: 'The cornea is a clear layer with no blood vessels, protected only by tears and a thin surface film. Once that film is scratched, germs enter a tissue that immunity does not reach quickly, so they spread and carve an ulcer within hours. The greatest cause in our time is contact lenses: sleeping in them, wearing them past their term, rinsing or storing them in water instead of solution, and swimming or showering in them. Then come work and farming injuries, especially wounds from plant matter, which is the gateway for fungi. Corneal defence is also weakened in severe dry eye, in lid palsy that prevents closure so the eye dries at night, in diabetes, and in anyone using steroid drops without supervision. There is also a herpes infection that lodges in the nerve and returns in a characteristic branching pattern, and a rare, very dangerous parasite that comes from water.'
  },
  diagnosis: {
    ar: 'يُصبغ سطح العين بصبغة برتقالية وتُفحص بضوء أزرق، فيلمع كل موضع سقط عنه الغشاء السطحي ويظهر شكل الإصابة: نقطة، أو تشعّبات كالغصن تعني الهربس، أو رقعة كثيفة تعني قرحة. ثم يُفحص بالمصباح الشقّي لقياس عمق القرحة واتساعها، ولرؤية ما إذا كان صديد قد تجمّع في مقدّم العين وهذه علامة شدّة. وفي القرح الكبيرة أو التي لم تستجب تُؤخذ كشطة من حافة القرحة وتُزرع لمعرفة الجرثومة أو الفطر بالضبط، ويُطلب فحص خاص للطفيلي عند لابسي العدسات. وتُفحص العدسة وعلبتها ومحلولها في المختبر أحياناً لأنها كثيراً ما تكون المصدر. ويُقاس البصر ويُتابَع يومياً في البداية، لأن تحسّنه أو تدهوره هو الحكم الحقيقي على نجاح العلاج.',
    en: 'The surface of the eye is stained with an orange dye and examined under blue light, so every place where the surface film has been lost glows and the shape of the lesion appears: a dot, branching lines that mean herpes, or a dense patch that means an ulcer. The slit lamp then measures the depth and width of the ulcer and shows whether pus has collected in the front of the eye, which is a sign of severity. In large ulcers, or those that have not responded, a scraping is taken from the ulcer edge and cultured to identify the exact germ or fungus, and a special test for the parasite is requested in lens wearers. The lens, its case and its solution are sometimes sent to the laboratory, since they are often the source. Vision is measured and followed daily at first, because its improvement or decline is the real verdict on the treatment.'
  },
  treatment: {
    ar: 'القاعدة الأولى أن تُخلع العدسات اللاصقة فوراً ولا تُلبس حتى يأذن الطبيب، وألا تُغطّى العين بضمّاد لأن التغطية تخلق بيئة دافئة رطبة تسرّع العدوى. والعلاج قطرات مضادّة للجراثيم يختار الطبيب نوعها حسب المتوقّع ثم يعدّلها على نتيجة الزرع، وتُقطّر بفواصل متقاربة جداً في اليوم الأول قد تصل إلى كل ساعة ليلاً ونهاراً، وهذا وحده سبب إدخال بعض المرضى المستشفى. وإن كانت العلّة فيروسية فالعلاج مضادّ للفيروس، وإن كانت فطرية أو طفيلية فالعلاج أطول بكثير وقد يمتدّ شهوراً. والكورتيزون سلاح ذو حدّين لا يضعه إلا طبيب العيون وفي وقته، لأنه فوق عدوى نشطة يوسّع القرحة. وتُتابَع الحالة كل يوم أو يومين، وإن ثُقبت القرنية أو تُركت ندبة على محور الإبصار احتاج الأمر ترقيعاً أو زرع قرنية لاحقاً.',
    en: 'The first rule is that contact lenses come out at once and are not worn again until the doctor allows it, and that the eye is not covered with a patch, because covering creates a warm, moist bed that speeds the infection. Treatment is antibacterial drops whose type the doctor chooses by what is expected, then adjusts on the culture result; they are given at very close intervals on the first day, possibly hourly day and night, and that alone is why some patients are admitted. If the cause is viral, treatment is antiviral; if fungal or parasitic, it is far longer and may run for months. Steroid is a double-edged weapon placed only by the ophthalmologist and only at the right moment, because over an active infection it widens the ulcer. The case is reviewed every day or two, and if the cornea perforates or a scar is left on the visual axis, a graft or corneal transplant is needed later.'
  },
  seeDoctor: {
    ar: 'طوارئ عيون في اليوم نفسه إن ألمت عينك ألماً حقيقياً واحمرّت ولم تحتمل الضوء، وبالأخصّ إن كنت تلبس عدسات لاصقة — اخلعها في الحال واحتفظ بها وبعلبتها لتُفحص، ولا تنم على أمل أن يهدأ الأمر وحده. اذهب فوراً أيضاً إن رأيت بقعة بيضاء على سواد العين، أو هبط بصرك، أو تجمّع ما يشبه الصديد داخل مقدّم العين، أو دخلت عينك شظية أو مادة كيميائية. وإن كانت الإصابة بمادة كيميائية فاغسل العين بماء نظيف جارٍ عشرين دقيقة متواصلة قبل أن تتحرّك إلى المستشفى. ولا تستعمل قطرة موجودة في البيت من وصفة قديمة ولا قطرة تُخفي الاحمرار ولا قطرة مخدّرة، فكلها تؤجّل التشخيص وتزيد الضرر. أما احمرار خفيف بلا ألم ولا ضعف بصر مع رشح وزكام فيُراجَع في موعد عادي.',
    en: 'Eye emergency the same day if your eye truly hurts, is red and cannot bear light, and above all if you wear contact lenses: take them out at once and keep them with their case to be examined, and do not sleep hoping it will settle by itself. Go immediately too if you see a white spot on the dark part of the eye, if your vision drops, if something like pus collects inside the front of the eye, or if a splinter or a chemical has entered. If the injury is chemical, wash the eye under clean running water for twenty unbroken minutes before setting off for hospital. Do not use a drop found at home from an old prescription, nor a redness-hiding drop, nor an anaesthetic drop, since all of them delay the diagnosis and deepen the damage. Mild redness with no pain and no loss of vision, alongside a runny nose and a cold, can be seen at an ordinary appointment.'
  },
  updated: '2026-09-08'
};

DX_BODY['keratoconus'] = {
  symptoms: {
    ar: 'يبدأ عادةً في المراهقة أو أوائل العشرينات بضعف نظر يزداد بسرعة غير معتادة: تتغيّر النظارة كل بضعة أشهر ولا يرتاح صاحبها لأي مقاس، ويقول إنه يرى بها ولا يرى بها. والصورة تتشوّه لا تغيم فقط: تظهر أشباح وظلال حول الحروف، ويُرى القمر أو المصباح بعدّة نسخ متداخلة، وتنتشر هالات وأشعة حول أضواء السيارات ليلاً حتى تصعب القيادة. ومعها حساسية للضوء وحكّة وعين تُفرك كثيراً، والفرك نفسه جزء من المرض لا عرَض له وحسب. وتتفاوت العينان فتكون إحداهما أسوأ من الأخرى بوضوح. وفي مرحلة متقدّمة أقلّ شيوعاً يتسرّب سائل داخل القرنية فجأةً فتضبّب الرؤية بشدّة مع ألم واحمرار ودمع خلال أيام.',
    en: 'It usually begins in the teens or early twenties with sight that worsens unusually fast: the spectacle prescription changes every few months and no strength satisfies its owner, who says he sees with them and does not see with them. The image distorts rather than merely blurring: ghosts and shadows appear around letters, the moon or a lamp is seen as several overlapping copies, and haloes and streaks spread around car headlights at night until driving becomes hard. With this come light sensitivity, itching and an eye that is rubbed a great deal, and the rubbing itself is part of the disease and not only a symptom. The two eyes differ, one clearly worse than the other. At a less common advanced stage, fluid suddenly seeps inside the cornea, so vision fogs severely with pain, redness and watering over days.'
  },
  cause: {
    ar: 'القرنية تستمدّ صلابتها من ألياف متينة منتظمة، وفي هذا المرض تضعف روابط هذه الألياف فترقّ القرنية وتستسلم لضغط العين من الداخل فتبرز كمخروط. والسبب مركّب: استعداد وراثي واضح، فكثير من المصابين لهم قريب مصاب، يضاف إليه محرّض ميكانيكي رئيسي هو فرك العين المتكرّر بقوّة. ولهذا يكثر عند أصحاب الحساسية والربو والإكزيما والتهاب الملتحمة الربيعي لأنهم يفركون عيونهم يومياً، وعند من ينام على وجهه ضاغطاً عينه في الوسادة. ويرتبط أيضاً بمتلازمات وراثية معيّنة كمتلازمة داون وببعض أمراض النسيج الضامّ. والمرض يتقدّم في سنوات الشباب ثم يستقرّ غالباً بعد الثلاثينات، ولهذا فاكتشافه مبكراً هو الفارق كله بين حالة تُثبَّت وحالة تنتهي إلى زرع قرنية.',
    en: 'The cornea owes its firmness to strong, orderly fibres, and in this disease the bonds between those fibres weaken, so the cornea thins, yields to the pressure inside the eye and bulges into a cone. The cause is mixed: a clear inherited predisposition, since many of those affected have an affected relative, joined to one main mechanical trigger, repeated forceful eye rubbing. That is why it is common in people with allergy, asthma, eczema and spring conjunctivitis, who rub their eyes daily, and in those who sleep face down pressing an eye into the pillow. It is also linked to certain inherited syndromes such as Down syndrome and to some connective tissue disorders. The disease advances through the years of youth and then usually settles after the thirties, which is why finding it early is the whole difference between a case that is stabilised and one that ends in a corneal transplant.'
  },
  diagnosis: {
    ar: 'لا يُشخَّص بقياس النظر وحده بل بخريطة القرنية: جهاز يرسم سطحها الأمامي والخلفي وسماكتها نقطةً نقطة، فيُظهر البروز وموضعه ودرجته قبل أن يشعر المريض بشيء، ويُظهر أرقّ نقطة فيها. وهذا الفحص هو المعيار، وهو نفسه ما يُطلب لكل من ينوي عملية تصحيح إبصار بالليزر، لأن إجراء الليزر على قرنية مخروطية خفيّة يسرّع تدهورها ويحوّل مشكلة قابلة للضبط إلى مشكلة كبيرة. ويُفحص المريض بالمصباح الشقّي فتُرى علامات مميّزة كخطوط رفيعة في عمق القرنية وحلقة صبغية عند قاعدة المخروط وترقّق واضح في قمّته. ويُقارن الفحص بفحص سابق، لأن الحكم الأهمّ ليس وجود المرض بل هل هو يتقدّم أم استقرّ، ولهذا تُعاد الخريطة كل بضعة أشهر في السنوات الأولى.',
    en: 'It is not diagnosed by measuring sight alone but by corneal mapping: a device that plots the front and back surfaces and the thickness point by point, revealing the bulge, its position and its degree before the patient feels anything, and showing the thinnest point. This scan is the standard, and it is the same one requested for anyone considering laser vision correction, because performing laser on a hidden keratoconic cornea speeds its decline and turns a controllable problem into a large one. The patient is also examined at the slit lamp, where characteristic signs are seen: fine lines deep in the cornea, a pigmented ring at the base of the cone and clear thinning at its apex. The scan is compared with an earlier one, because the more important judgement is not whether the disease exists but whether it is advancing or has settled, so the map is repeated every few months in the early years.'
  },
  treatment: {
    ar: 'العلاج طبقتان: إيقاف التقدّم، وتحسين الرؤية. لإيقاف التقدّم يوجد إجراء يقوّي روابط ألياف القرنية بمزيج من فيتامين وضوء فوق بنفسجي مضبوط، ويُجرى مرة واحدة غالباً، وقيمته أنه يثبّت الحالة لا أنه يعيد النظر، ولهذا يُقدَّم مبكراً لمن ثبت أن قرنيته تتدهور. أما الرؤية فتُصحَّح بالنظارة في البداية، ثم بعدسات لاصقة صلبة نفّاذة للأكسجين، أو عدسات صلبة كبيرة ترتكز على بياض العين وتصنع سطحاً منتظماً أمام المخروط فتعيد وضوحاً مدهشاً. وفي حالات مختارة تُزرع حلقات دقيقة داخل القرنية لتسطّح المخروط قليلاً. وإن بلغت الحالة حدّ الندبة أو لم تعد أي عدسة تُحتمل فزرع القرنية هو الحلّ ونتائجه جيدة عموماً. ويبقى الأهمّ والأرخص: التوقّف تماماً عن فرك العين وعلاج الحساسية التي تدفع إليه.',
    en: 'Treatment has two layers: stopping the progression, and improving the vision. To stop progression there is a procedure that strengthens the bonds between the corneal fibres using a vitamin combined with controlled ultraviolet light; it is usually done once, and its value is that it stabilises the condition rather than restoring sight, which is why it is offered early to anyone whose cornea is shown to be deteriorating. Vision itself is corrected first with spectacles, then with rigid oxygen-permeable contact lenses, or large rigid lenses that rest on the white of the eye and create an even surface in front of the cone, often restoring striking clarity. In selected cases fine rings are implanted inside the cornea to flatten the cone a little. If scarring is reached, or no lens can be tolerated any longer, corneal transplantation is the answer and its results are generally good. The most important and cheapest measure remains: stopping eye rubbing altogether and treating the allergy that drives it.'
  },
  seeDoctor: {
    ar: 'احجز عند طبيب عيون خلال أسابيع لا خلال سنة إذا تغيّرت نظارتك مرتين أو أكثر في عام واحد، أو لم تعد أي نظارة تعطيك رؤية مريحة، أو صرت ترى أشباحاً وظلالاً حول الحروف وهالات حول الأضواء ليلاً. واطلب صراحةً خريطة للقرنية إن كنت مراهقاً أو شاباً وتفرك عينيك كثيراً، أو عندك حساسية عين مزمنة، أو في العائلة مصاب. ولا تُجرِ عملية ليزر لتصحيح النظر قبل هذه الخريطة مهما بدا نظرك مستقرّاً. وراجع الطوارئ في اليوم نفسه إن ضبّبت رؤيتك فجأةً بشدّة مع ألم واحمرار ودمع غزير، فقد يكون سائل تسرّب داخل القرنية وهي حالة تحتاج علاجاً عاجلاً وإن كانت تهدأ غالباً وتترك ندبة. أما إن كان تشخيصك قديماً ومستقرّاً فالتزم بإعادة الخريطة في مواعيدها فهي التي تكشف التدهور في وقته.',
    en: 'Book with an ophthalmologist within weeks rather than within a year if your spectacle prescription has changed twice or more in one year, if no pair of glasses gives you comfortable vision any longer, or if you now see ghosts and shadows around letters and haloes around lights at night. Ask explicitly for a corneal map if you are a teenager or young adult who rubs the eyes a great deal, or you have chronic eye allergy, or there is an affected relative. Do not undergo laser vision correction before that map, however stable your sight seems. Attend emergency care the same day if your vision suddenly fogs badly with pain, redness and heavy watering, since fluid may have seeped inside the cornea; that needs urgent treatment even though it usually settles and leaves a scar. If your diagnosis is old and stable, keep to the repeat mapping appointments, for they are what reveal deterioration in time.'
  },
  updated: '2026-09-08'
};

DX_BODY['optic-neuritis'] = {
  symptoms: {
    ar: 'يبدأ بضبابية في عين واحدة تتقدّم خلال ساعات إلى أيام قليلة، وكأن على العين زجاجاً مغبّراً أو كأن الإضاءة خفتت في تلك العين وحدها. ويصحبها ألم غائر خلف العين يزداد عند تحريكها يميناً وشمالاً أو للأعلى، وهذا الألم من أوضح ما يميّزها. والألوان تذبل قبل أن يذبل الوضوح: الأحمر يبدو باهتاً أو بنّياً أو مغسولاً في العين المصابة إذا قورن بالسليمة، والفرق يظهر بمجرّد إغماض إحداهما بالتناوب. وقد تظهر بقعة معتمة في وسط النظر أو نقص في جزء من المجال. ومن العلامات المعروفة أن الرؤية تسوء مؤقّتاً مع ارتفاع حرارة الجسم بعد رياضة أو حمّام ساخن ثم ترجع. وتصيب غالباً الشباب، والنساء أكثر.',
    en: 'It begins with blurring in one eye that advances over hours to a few days, as if dusty glass lay over it, or as though the lighting had dimmed in that eye alone. With it comes a deep ache behind the eye that worsens on moving it left, right or upward, and this pain is among its clearest marks. Colours fade before sharpness does: red looks dull, brown or washed out in the affected eye compared with the good one, and the difference shows the moment you close each eye in turn. A dark patch may appear in the middle of the vision, or part of the field may be missing. It is well known that the vision worsens temporarily when body temperature rises after exercise or a hot bath, then recovers. It mostly strikes young adults, and women more often.'
  },
  cause: {
    ar: 'العصب البصري حزمة من ألياف مغلّفة بمادة عازلة تسرّع نقل الإشارة، فإذا هاجمت المناعة هذا الغلاف التهب العصب وتباطأت الإشارة وتشوّهت، فيصل إلى الدماغ منظر باهت ناقص. وأشهر ما يقف خلفه هو التصلّب المتعدّد، حتى إن التهاب العصب البصري قد يكون أول ظهور له قبل أي عرض آخر بسنوات، وليس كل من أصيب به يصير مصاباً بالتصلّب. وهناك أمراض مناعية أخرى تصيب العصب بصورة أشدّ وتحتاج تمييزاً مبكراً لأن علاجها يختلف. وقد يلتهب العصب بعد عدوى فيروسية عند الأطفال، أو مع التهاب الجيوب المجاور، أو مع أمراض جهازية كالساركويد والذئبة، أو نتيجة نقص فيتامينات معيّنة أو تسمّم أو دواء، وهذي الأخيرة تصيب العينين معاً غالباً.',
    en: 'The optic nerve is a bundle of fibres wrapped in an insulating sheath that speeds the signal, and when immunity attacks that sheath the nerve inflames, so the signal slows and distorts and a dim, incomplete picture reaches the brain. The best known condition behind it is multiple sclerosis; optic neuritis may indeed be its first appearance years before any other symptom, though not everyone who has it goes on to develop the disease. Other immune disorders strike the nerve more severely and must be told apart early, because their treatment differs. The nerve may also inflame after a viral infection in children, alongside sinus infection, with systemic diseases such as sarcoidosis and lupus, or from certain vitamin deficiencies, poisoning or a medicine, and these last usually affect both eyes together.'
  },
  diagnosis: {
    ar: 'يبدأ بفحص سريري بسيط وحاسم: يقارن الطبيب إدراك العينين للألوان ولشدّة الضوء، ثم يحرّك ضوءاً بالتناوب بين العينين فيرى استجابة بؤبؤ العين المصابة أضعف، وهذه علامة تدلّ على خلل في العصب نفسه لا في العدسة ولا في الشبكية. ويُفحص قاع العين فقد يبدو رأس العصب متورّماً أو طبيعياً تماماً، وكونه طبيعياً لا ينفي شيئاً لأن الالتهاب قد يكون خلفه. ثم يُقاس مجال الرؤية لتحديد موضع النقص، ويُصوَّر العصب والشبكية بالتصوير المقطعي البصري لقياس سماكة الألياف. والفحص الحاسم هو الرنين المغناطيسي للدماغ والعصب البصري بالصبغة، فهو يُظهر التهاب العصب ويكشف في الوقت نفسه إن كانت في الدماغ بقع أخرى صامتة تغيّر التشخيص والمآل. وتُطلب تحاليل دم مناعية للتفريق بين الأنواع.',
    en: 'It starts with a simple and decisive bedside examination: the doctor compares how the two eyes perceive colour and light intensity, then swings a light between them and sees the affected pupil respond more weakly, a sign pointing to a fault in the nerve itself rather than the lens or the retina. The back of the eye is examined, where the nerve head may look swollen or entirely normal, and a normal appearance rules nothing out, since the inflammation may lie behind it. The visual field is then measured to locate the defect, and the nerve and retina imaged by optical coherence tomography to measure fibre thickness. The decisive test is magnetic resonance imaging of the brain and optic nerve with contrast, which shows the inflamed nerve and at the same time reveals whether other silent patches exist in the brain, which changes both diagnosis and outlook. Immune blood tests are requested to separate the types.'
  },
  treatment: {
    ar: 'أغلب الحالات تتحسّن من تلقاء نفسها خلال أسابيع، ويرجع البصر إلى قريب مما كان عليه خلال شهرين إلى ستة أشهر، وقد يبقى فرق طفيف في نصاعة الألوان أو التباين تلاحظه أنت ولا يلاحظه غيرك. ودور العلاج هو تسريع هذا التحسّن لا تغيير النتيجة النهائية غالباً، ويكون بجرعات عالية من مضادّ التهاب يُعطى في الوريد بضعة أيام في المستشفى ثم يُخفَّض تدريجياً، ويقرّره طبيب الأعصاب أو العيون حسب الشدّة. وهناك أنواع مناعية أشدّ لا تنتظر، فتُعالج بسرعة وقد تحتاج تنقية للدم أو أدوية تعديل مناعة طويلة الأمد لمنع الهجمات. وإن كشف الرنين بقعاً في الدماغ فالحديث ينتقل إلى علاج وقائي للتصلّب المتعدّد يديره طبيب أعصاب. ويُنصح المريض بضبط الحرارة والراحة أثناء النوبة لأن الحرّ يفاقم العرض مؤقّتاً.',
    en: 'Most cases improve of their own accord over weeks, and vision returns close to what it was within two to six months, though a slight difference in colour vividness or contrast may remain that you notice and others do not. The role of treatment is to speed that recovery rather than, usually, to change the final result: high doses of an anti-inflammatory given into a vein for a few days in hospital and then tapered, decided by the neurologist or ophthalmologist according to severity. There are more aggressive immune types that do not wait; they are treated quickly and may need blood purification or long-term immune-modifying medicines to prevent further attacks. If the scan reveals patches in the brain, the discussion moves to preventive treatment for multiple sclerosis managed by a neurologist. During the attack the patient is advised to keep cool and rest, since heat temporarily worsens the symptom.'
  },
  seeDoctor: {
    ar: 'راجع طبيب عيون أو طوارئ خلال يوم أو يومين إذا بهت بصر عين واحدة خلال ساعات أو أيام، خصوصاً إن صحبه ألم عند تحريك العين أو بدا الأحمر باهتاً في تلك العين. ولا تنتظر أسبوعاً لترى إن كان سيتحسّن، فالتمييز بين هذا وبين انسداد وعاء أو ارتفاع ضغط داخل الرأس أو ورم يضغط العصب يحتاج فحصاً وتصويراً لا انتظاراً. واطلب الطوارئ فوراً إن أصابت العينين معاً، أو صحبها صداع شديد جديد أو قيء، أو ضعف في طرف أو تنميل أو اضطراب في الاتزان أو التبوّل، أو إن كنت فوق الخمسين وجاءك معها ألم في الصدغ أو الفكّ. ومن سبق أن أصيب بها فعليه أن يعرف أن عودة الأعراض مع الحرارة أمر معتاد ولا يعني انتكاسة، أما عرض جديد يستمرّ أكثر من يوم فيستحقّ مراجعة.',
    en: 'See an ophthalmologist or emergency department within a day or two if the vision of one eye dims over hours or days, especially with pain on moving the eye or if red looks washed out in that eye. Do not wait a week to see whether it improves, because telling this apart from a blocked vessel, raised pressure inside the head or a tumour pressing on the nerve needs examination and imaging rather than waiting. Seek emergency care at once if both eyes are affected, if a severe new headache or vomiting comes with it, if there is limb weakness, numbness, unsteadiness or bladder disturbance, or if you are over fifty and have pain in the temple or jaw. Anyone who has had it before should know that symptoms returning with heat is expected and does not mean a relapse, whereas a new symptom lasting more than a day deserves review.'
  },
  updated: '2026-09-08'
};

DX_BODY['vitreous-floaters'] = {
  symptoms: {
    ar: 'أشكال شفّافة تسبح في مجال النظر: نقاط أو خيوط أو خيط عنكبوت أو حلقة، تتحرّك مع حركة العين ثم تنجرف متأخّرة عنها قليلاً، وتهرب حين تحاول النظر إليها مباشرة. وتُرى أوضح ما تكون أمام سماء صافية أو جدار أبيض أو شاشة بيضاء، وتكاد تختفي في الإضاءة الخافتة. وأكثرها قديم ثابت اعتاده صاحبه منذ سنين. أما انفصال الجسم الزجاجي فيعلن نفسه دفعةً واحدة: عوّامة كبيرة جديدة أو حلقة تظهر في يوم واحد، ومعها ومضات ضوء قصيرة في طرف المجال تُرى أوضح ليلاً أو عند تحريك العين بسرعة. وهذا في ذاته أمر شائع مع العمر ولا يعني كارثة، لكنه يفتح نافذة أسابيع يجب أن تُفحص فيها الشبكية.',
    en: 'Transparent shapes drift across the field of view: dots, threads, a cobweb or a ring, moving with the eye and then drifting on slightly after it, and slipping away when you try to look at them directly. They are clearest against a plain sky, a white wall or a white screen, and almost vanish in dim light. Most are old and settled, and their owner has lived with them for years. A vitreous detachment, by contrast, announces itself all at once: a large new floater or a ring appearing in a single day, together with brief flashes of light at the edge of the field, clearest at night or on moving the eye quickly. This in itself is common with age and is no catastrophe, but it opens a window of weeks in which the retina must be examined.'
  },
  cause: {
    ar: 'يملأ داخل العين هلام شفّاف مشدود إلى الشبكية، وفيه ألياف دقيقة. ومع العمر يتسيّل هذا الهلام وينكمش وتتكتّل أليافه، فتلقي ظلالها على الشبكية فتُرى كعوّامات. ثم يأتي يوم ينفصل فيه الهلام عن سطح الشبكية انفصالاً كاملاً، فتظهر الحلقة والومضات معاً، والومضة نفسها إنما هي شدّ ميكانيكي على الشبكية تفسّره العين ضوءاً. وأكثر ما يعجّل ذلك قصر النظر الشديد، وعملية الساد، وضربة على العين، والالتهاب داخل العين. والمشكلة أن هذا الشدّ قد يمزّق الشبكية في نقطة ضعيفة عند نسبة قليلة من الناس، ومن هؤلاء من يتطوّر عنده الأمر إلى انفصال شبكي. وقد تنشأ عوّامات أخرى من نزيف داخل العين أو من خلايا التهابية، وهذي لها قصة مختلفة تماماً.',
    en: 'The inside of the eye is filled with a clear gel attached to the retina and threaded with fine fibres. With age this gel liquefies and shrinks and its fibres clump, casting shadows on the retina that are seen as floaters. Then comes a day when the gel separates completely from the retinal surface, and the ring and the flashes appear together; the flash itself is a mechanical tug on the retina that the eye interprets as light. What hastens this most is severe short-sightedness, cataract surgery, a blow to the eye and inflammation inside it. The difficulty is that in a small proportion of people this tugging tears the retina at a weak point, and in some of those it goes on to a retinal detachment. Other floaters may arise from bleeding inside the eye or from inflammatory cells, and those have an entirely different story.'
  },
  diagnosis: {
    ar: 'الفحص المطلوب واحد ولا بديل له: توسيع البؤبؤ بقطرة ثم فحص قاع العين بكاملها حتى أطرافها البعيدة بمنظار غير مباشر، لأن التمزّق يقع غالباً في المحيط لا في المركز. ويُضاف عند الحاجة فحص بعدسة خاصة على المصباح الشقّي وضغط لطيف على محيط المقلة لرؤية آخر ما يمكن رؤيته من الشبكية. ويبحث الطبيب أثناء ذلك عن ثلاثة أشياء: تمزّق، أو خلايا صبغية سابحة في الهلام وهي علامة تدلّ على تمزّق حتى لو لم يُرَ، أو نزيف صغير. وإن حجب نزيف الرؤية استُعملت الموجات الصوتية على العين ثم أُعيد الفحص بعد أيام. ومن كانت عنده هذه الأعراض ولم يُوجد تمزّق يُعاد فحصه بعد أسابيع قليلة، لأن جزءاً من التمزّقات يظهر متأخراً.',
    en: 'The examination required is one and has no substitute: dilating the pupil with drops, then examining the whole back of the eye to its far edges with an indirect scope, because a tear usually lies in the periphery rather than the centre. Where needed, a special lens at the slit lamp and gentle pressure around the globe are added to see the last of the retina that can be seen. During this the doctor looks for three things: a tear; pigment cells floating in the gel, a sign that points to a tear even when none is seen; or a small haemorrhage. If bleeding blocks the view, ultrasound of the eye is used and the examination repeated after some days. Anyone with these symptoms in whom no tear is found is re-examined a few weeks later, because a proportion of tears show up late.'
  },
  treatment: {
    ar: 'العوّامات السليمة لا تُعالج ولا تحتاج علاجاً، ومع الوقت يهبط أكثرها خارج محور النظر ويتعوّد الدماغ عليها فيكفّ عن ملاحظتها، وهذا هو المسار المعتاد في أشهر قليلة. ويساعد على احتمالها أن تُقلَّل الإضاءة الخلفية الشديدة وأن تُحرَّك العين لأعلى وأسفل لإزاحة العوّامة عن مركز الرؤية. أما إن وُجد تمزّق في الشبكية فهذا هو الأمر الذي يُعالج: يُحاصر التمزّق بالليزر أو بالتجميد في العيادة في جلسة قصيرة، فيلتحم حوله نسيج يمنع تسرّب السائل ويمنع الانفصال، وهذا إجراء وقائي بسيط قيمته أنه يجنّب عملية كبيرة لاحقاً. وفي حالات نادرة جداً تكون العوّامات كثيفة معطّلة للحياة فيُناقَش استئصال الهلام جراحياً بعد موازنة صريحة بين فائدته ومخاطره على عين ترى جيداً.',
    en: 'Harmless floaters are not treated and need no treatment; with time most sink out of the visual axis and the brain grows used to them and stops noticing, which is the usual course over a few months. Reducing harsh backlighting and moving the eye up and down to shift a floater off the centre of vision both help in tolerating them. If a retinal tear is found, however, that is what is treated: the tear is walled off with laser or freezing in the clinic in a short session, so scar tissue seals around it, stops fluid seeping through and prevents detachment. This is a simple preventive step whose worth is that it spares a major operation later. In very rare cases the floaters are so dense that they disrupt life, and surgical removal of the gel is discussed after an honest weighing of its benefit against its risks to an eye that sees well.'
  },
  seeDoctor: {
    ar: 'اذهب إلى طبيب عيون خلال أربع وعشرين إلى ثمان وأربعين ساعة إذا ظهرت عوّامات جديدة دفعةً واحدة، أو رأيت ومضات ضوء لم تعهدها، أو تغيّر شكل عوّاماتك القديمة وعددها فجأةً. واذهب إلى الطوارئ في الحال ولا تنتظر موعداً إذا رأيت ظلاً أو ستارة تقتطع جزءاً من مجال النظر، أو هبط بصرك، أو انهمر أمامك سيل كثيف من النقاط السوداء يشبه دخاناً أو رذاذ فلفل فقد يكون نزيفاً داخل العين. وهذه العلامات تعنيك أكثر إن كنت قصير نظر شديداً أو أُجريت لك عملية ساد أو أُصبت في عينك. أما عوّامات قديمة ثابتة منذ سنين لم يتغيّر شكلها فلا تحتاج أكثر من ذكرها في الفحص الدوري، ولا تستحقّ قلقاً يومياً.',
    en: 'See an ophthalmologist within twenty-four to forty-eight hours if new floaters appear all at once, if you see flashes of light you are not used to, or if the shape and number of your old floaters change suddenly. Go to the emergency department at once, without waiting for an appointment, if you see a shadow or curtain cutting into your field of view, if your vision drops, or if a dense shower of black dots like smoke or pepper pours in, since that may be bleeding inside the eye. These signs concern you all the more if you are severely short-sighted, have had cataract surgery, or have injured that eye. Old floaters, stable for years and unchanged in shape, need no more than a mention at your routine check and do not deserve daily worry.'
  },
  updated: '2026-09-08'
};

/* ==================== الجفن والدمع وسطح العين ==================== */

DX_BODY['stye-chalazion'] = {
  symptoms: {
    ar: 'الشحاذ يبدأ بإحساس بشيء يضغط في حافة الجفن، ثم ينتفخ الموضع خلال يوم أو يومين ويحمرّ ويؤلم عند اللمس وعند الرمش، وقد تظهر عليه نقطة صفراء صغيرة مثل رأس دمّل، ويتورّم الجفن كله أحياناً حتى يضيق فتح العين وتدمع. أما البردة فتبدأ كثيراً بشحاذ هدأ ألمه ولم يذهب أثره: كتلة مستديرة صلبة داخل الجفن لا تؤلم غالباً ولا تحمرّ، تبقى أسابيع أو أشهر وتُحسّ عند الجسّ كحصاة تحت الجلد، وإن كبرت ضغطت على القرنية فشوّشت الرؤية قليلاً. والفرق العملي بينهما بسيط: الشحاذ مؤلم حادّ قصير الأجل، والبردة كتلة صامتة طويلة الأجل. وتكرّرها في نفس الموضع أو في مواضع متعدّدة يشير إلى التهاب مزمن في حافة الجفن.',
    en: 'A stye starts as a feeling of something pressing in the lid margin, then the spot swells over a day or two, reddens and hurts on touch and on blinking, and a small yellow point like a boil head may appear on it; sometimes the whole lid swells until the eye barely opens and waters. A chalazion often begins as a stye whose pain has settled but whose trace has not gone: a round, firm lump inside the lid, usually painless and not red, lasting weeks or months and felt on touch like a pebble under the skin; if it grows it presses on the cornea and slightly blurs vision. The practical difference between them is simple: the stye is sharply painful and short-lived, the chalazion a silent, long-lasting lump. Repeated lumps in the same place, or in several places, point to chronic inflammation of the lid margin.'
  },
  cause: {
    ar: 'في حافة كل جفن صفّ من غدد دهنية تفرز طبقة زيتية تغطّي الدمعة وتمنعها من التبخّر السريع. فإذا غلظ هذا الزيت أو سُدّت فتحة الغدّة احتُبس الإفراز داخلها. فإن دخلت جراثيم الجلد المحتبس صار المكان التهاباً حادّاً مؤلماً وهو الشحاذ، وإن لم تدخل بقي الإفراز محبوساً فتكوّن حوله الجسم جداراً ليفياً وصارت كتلة باردة هي البردة. وأكبر ما يهيّئ لذلك التهاب حافة الجفن المزمن وقشور الرموش، ثم الوردية الجلدية، وجفاف العين، وسوء نظافة اليدين وفرك العين، وبقايا مساحيق التجميل التي لا تُزال ليلاً، وارتفاع دهون الدم عند بعض الناس، والتوتّر وقلّة النوم عبر تأثيرهما على المناعة الموضعية. والتكرار المستمرّ في موضع واحد بعينه عند كبار السنّ يستحقّ نظرة أدقّ.',
    en: 'Along each lid margin runs a row of oil glands that secrete a fatty layer covering the tear film and stopping it evaporating too fast. If that oil thickens or the gland opening blocks, the secretion is trapped inside. If skin bacteria enter the trapped material, the place becomes an acute, painful inflammation, the stye; if they do not, the secretion stays walled in and the body builds a fibrous shell around it, making the cold lump that is the chalazion. What most predisposes to this is chronic lid margin inflammation with crusting of the lashes, then skin rosacea, dry eye, poor hand hygiene and eye rubbing, cosmetic residue not removed at night, raised blood fats in some people, and stress and lack of sleep through their effect on local immunity. Persistent recurrence at one particular spot in an older person deserves a closer look.'
  },
  diagnosis: {
    ar: 'التشخيص سريري بالنظر والجسّ ولا يحتاج تحليلاً ولا أشعة: يقلب الطبيب الجفن لينظر إلى سطحه الداخلي فيرى فتحة الغدّة المسدودة أو الكتلة تحت الغشاء، ويفحص حافة الجفن بالمصباح الشقّي بحثاً عن قشور ورغوة في الدمع وغدد مسدودة، لأن ذلك يفسّر التكرار ويحدّد العلاج طويل الأمد. ويقيس البصر ويفحص القرنية إن كانت الكتلة كبيرة تضغط عليها. والمهمّ في هذا الفحص هو استبعاد ما يتنكّر في صورة بردة: التهاب منتشر في نسيج الجفن والمحجر وهو حالة خطيرة تصحبها حمّى وألم عند تحريك العين وجحوظ، أو ورم في الغدّة الدهنية يشبه بردة متكرّرة عنيدة في مكان واحد عند كبار السنّ. وفي هذي الحالة الأخيرة قد يُؤخذ جزء من النسيج للفحص المجهري.',
    en: 'The diagnosis is clinical, by looking and feeling, and needs no test or scan: the doctor turns the lid to inspect its inner surface, sees the blocked gland opening or the lump beneath the lining, and examines the lid margin at the slit lamp for crusts, froth in the tears and blocked glands, since these explain the recurrence and set the long-term treatment. Vision is measured and the cornea checked if a large lump is pressing on it. What matters most in this examination is excluding what disguises itself as a chalazion: spreading inflammation of the lid and orbital tissue, a serious condition with fever, pain on moving the eye and bulging; or a tumour of the oil gland, which resembles a stubborn chalazion recurring in one place in an older person. In that last case a piece of tissue may be taken for microscopic examination.'
  },
  treatment: {
    ar: 'العلاج الأساسي بسيط ومنزلي وأكثر الناس يهملونه أو يفعلونه ناقصاً: كمّادات دافئة على الجفن المغلق عشر دقائق مرتين إلى أربع مرات يومياً بحيث تبقى دافئة طوال المدّة، لأن الحرارة تذيب الزيت الغليظ فتفتح الغدّة، يتبعها تدليك لطيف لحافة الجفن باتجاه الرموش وتنظيفها بمنظّف مخصّص أو بشامبو أطفال مخفّف. وأكثر الشحاذات تُفرغ نفسها خلال أسبوع بهذا وحده. ولا يُعصر ولا يُفتح بإبرة في البيت إطلاقاً لأن ذلك ينشر الالتهاب في نسيج الجفن. ويصف الطبيب مرهماً مضادّاً للجراثيم إن انتشر الاحمرار، أو علاجاً بالفم إن التهب نسيج الجفن كله. أما البردة التي بقيت أكثر من شهر أو ضغطت على القرنية فتُفتح وتُفرَّغ في العيادة بتخدير موضعي في دقائق، أو يُحقن فيها دواء يذيبها. ومنع التكرار يكون بالعناية اليومية بحافة الجفن.',
    en: 'The mainstay is simple, done at home, and is what most people neglect or do half-heartedly: warm compresses on the closed lid for ten minutes two to four times a day, kept warm throughout, because heat melts the thickened oil and opens the gland; followed by gentle massage of the lid margin towards the lashes and cleaning it with a dedicated cleanser or diluted baby shampoo. Most styes drain themselves within a week on this alone. It must never be squeezed or opened with a needle at home, because that spreads the inflammation into the lid tissue. The doctor prescribes an antibacterial ointment if the redness spreads, or treatment by mouth if the whole lid becomes inflamed. A chalazion that has lasted more than a month, or is pressing on the cornea, is opened and emptied in the clinic under local anaesthetic in minutes, or injected with a medicine that dissolves it. Preventing recurrence rests on daily lid margin care.'
  },
  seeDoctor: {
    ar: 'راجع الطبيب خلال أيام إن لم يتحسّن الشحاذ بعد أسبوع من الكمّادات المنتظمة، أو إن بقيت الكتلة أكثر من شهر، أو كبرت حتى ضبّبت رؤيتك، أو تكرّرت في المكان نفسه أكثر من مرّتين. واذهب إلى الطوارئ في اليوم نفسه إذا انتشر الاحمرار والتورّم إلى الجفن كله وما حوله، أو صحبته حمّى أو رعشة، أو صار تحريك العين مؤلماً، أو بدت العين جاحظة أو تعرف أنك ترى مزدوجاً، أو هبط بصرك — فهذه علامات التهاب امتدّ إلى داخل المحجر وهو حالة تُعالج في المستشفى ولا تنتظر. واذهب أيضاً بسرعة إن كان المصاب طفلاً صغيراً وتورّم جفنه بسرعة. وأخيراً: كتلة عنيدة تعود في موضع واحد بعينه عند كبير السنّ، أو معها تساقط رموش في ذلك الموضع، تستحقّ فحصاً متخصّصاً ولا تُهمَل.',
    en: 'See a doctor within days if a stye has not improved after a week of regular compresses, if a lump has lasted more than a month, if it has grown enough to blur your vision, or if it has come back in the same place more than twice. Go to the emergency department the same day if redness and swelling spread to the whole lid and around it, if fever or shivering accompanies it, if moving the eye becomes painful, if the eye looks pushed forward, if you see double, or if your vision drops, because these are signs that inflammation has spread inside the orbit, which is treated in hospital and does not wait. Go quickly too if the affected person is a small child whose lid is swelling fast. Finally, a stubborn lump returning at one particular spot in an older person, or with loss of lashes there, deserves specialist examination and must not be ignored.'
  },
  updated: '2026-09-08'
};

DX_BODY['eyelid-malposition'] = {
  symptoms: {
    ar: 'في تدلّي الجفن ينزل الجفن العلوي حتى يقترب من البؤبؤ أو يغطّي طرفه، فيضيق مجال النظر من الأعلى، ويجد صاحبه نفسه يرفع حاجبيه أو يميل رأسه للخلف ليرى، ويشتدّ الأمر آخر النهار وعند التعب. وتثقل الجبهة ويصدّع الرأس من كثرة رفع الحاجب. أما انقلاب الجفن للخارج فيبعد حافته عن كرة العين فتفيض الدمعة على الخدّ باستمرار وتحمرّ الحافة الداخلية ويجفّ سطح العين ويلتهب. وفي انقلاب الجفن للداخل تنطبق الحافة على العين فتحكّ الرموش القرنية مع كل رمشة، فيشكو المصاب إحساساً دائماً برمل في عينه واحمراراً ودمعاً وحساسية للضوء، وقد لا يصف الأمر إلا بأن عينه لا ترتاح أبداً. وفي الحالات الثلاث قد يبدو الأمر شكلياً وهو ليس كذلك.',
    en: 'In ptosis the upper lid sinks until it nears the pupil or covers its edge, so the field of view narrows from above; the person finds himself raising his eyebrows or tilting his head back to see, and it worsens at the end of the day and with tiredness. The forehead grows heavy and headaches follow from constant brow lifting. In an outward-turning lid the margin falls away from the eyeball, so tears spill down the cheek constantly, the inner margin reddens and the surface of the eye dries and inflames. In an inward-turning lid the margin presses against the eye so the lashes scrape the cornea with every blink, and the sufferer complains of a permanent feeling of sand in the eye, redness, watering and light sensitivity, sometimes describing it only as an eye that is never comfortable. In all three the problem may look cosmetic and is not.'
  },
  cause: {
    ar: 'أشيع أسباب التدلّي هو الشيخوخة نفسها: الوتر الذي يرفع الجفن يترقّق وينزلق عن موضعه فيهبط الجفن بلا أي مرض آخر، ويعجّل ذلك لبس العدسات اللاصقة سنوات طويلة وفرك العين وعمليات العين السابقة. لكن التدلّي قد يكون علامة مرض عصبي: شلل العصب المحرّك للعين، أو الوهن العضلي الذي يتغيّر فيه التدلّي خلال اليوم ويسوء بالتعب، أو خلل في العصب الودّي يصحبه صغر البؤبؤ في الجهة نفسها. ويولد بعض الأطفال به فيحجب البصر عن عين تنمو فتصير كسولة. أما انقلاب الجفن للخارج أو للداخل فسببه الأول ارتخاء أنسجة الجفن مع العمر، ويضاف إليه الندبات بعد الحروق والجراحة والتشمّس المزمن، والتشنّج المتكرّر للجفن، وشلل عصب الوجه الذي يرخي الجفن السفلي.',
    en: 'The commonest cause of drooping is age itself: the tendon that lifts the lid thins and slips from its attachment, so the lid sinks with no other disease; long years of contact lens wear, eye rubbing and previous eye surgery hasten it. But drooping can be the sign of a nerve disease: palsy of the nerve that moves the eye; myasthenia, in which the droop varies through the day and worsens with fatigue; or a fault in the sympathetic nerve, accompanied by a small pupil on the same side. Some children are born with it, so it blocks vision from a developing eye, which then becomes lazy. Outward or inward turning of the lid is caused first by slackening of the lid tissues with age, to which are added scarring after burns, surgery and chronic sun exposure, repeated lid spasm, and facial nerve palsy that leaves the lower lid slack.'
  },
  diagnosis: {
    ar: 'يقيس الطبيب بالمسطرة مقدار ما يغطّيه الجفن من القرنية وقوّة العضلة الرافعة وارتفاع ثنية الجفن، ويصوّر الحالة، لأن هذي الأرقام هي التي تحدّد نوع الجراحة ومقدارها. ثم يفحص مجال الرؤية العلوي مرّتين، مرة والجفن على حاله ومرة وهو مرفوع باليد، والفرق بينهما هو الدليل العملي على أن التدلّي يعوق البصر فعلاً لا شكلاً. ويبحث في الوقت نفسه عن سبب عصبي: يقارن حجم البؤبؤين، ويسأل عن ازدواج الرؤية وصعوبة البلع وضعف عام يزيد بالتعب، ويطلب تحاليل أو تصويراً إن اشتبه. وفي انقلاب الجفن يشدّ الطبيب الجفن ويتركه ليقيس مرونته، ويصبغ سطح العين ليرى ما خدشته الرموش من القرنية. ويُختبر إفراز الدمع وسلامة إغلاق الجفن قبل أي عملية.',
    en: 'The doctor measures with a ruler how much of the cornea the lid covers, the strength of the lifting muscle and the height of the lid crease, and photographs the case, because these figures decide the type and amount of surgery. The upper visual field is then tested twice, once with the lid as it is and once with it held up by hand, and the difference between them is the practical proof that the droop truly obstructs sight rather than appearance. At the same time a nerve cause is sought: the two pupils are compared, and questions are asked about double vision, difficulty swallowing and general weakness that increases with fatigue, with tests or imaging if suspicion arises. In lid malposition the doctor pulls the lid and releases it to measure its elasticity, and stains the surface of the eye to see what the lashes have scraped from the cornea. Tear production and the completeness of lid closure are tested before any operation.'
  },
  treatment: {
    ar: 'أكثر هذي الحالات علاجها جراحي بسيط يُجرى بتخدير موضعي في العيادة أو غرفة العمليات وينتهي في وقت قصير. ففي التدلّي المكتسب يُعاد ربط الوتر المرتخي إلى موضعه أو يُقصَّر بمقدار محسوب، وفي الجفن السفلي المنقلب يُشدّ الجفن ويُثبَّت وتره الخارجي فيعود ملامساً لكرة العين. وتحديد المقدار هو الفنّ كله، لأن الزيادة تمنع إغلاق العين ليلاً فتجفّ القرنية والنقصان يترك المشكلة. وقبل الجراحة وبعدها تُعالج العين نفسها بمرطّبات ومرهم ليلي لحماية القرنية، وقد تُغطّى العين ليلاً بشريط رقيق. وإن كان السبب عصبياً فالعلاج يتّجه إلى المرض الأصلي أولاً ولا يُتعجّل بالجراحة قبل استقرار الحالة أشهراً. وفي تدلّي المولود الذي يحجب البؤبؤ لا يُنتظر، لأن العين تتعلّم الكسل بسرعة.',
    en: 'Most of these conditions are treated by simple surgery under local anaesthetic in the clinic or theatre, finished in a short time. In acquired drooping the slackened tendon is reattached to its place or shortened by a calculated amount; in an out-turned lower lid the lid is tightened and its outer tendon fixed so that it lies against the eyeball again. Judging the amount is the whole art, since too much prevents the eye closing at night so the cornea dries, and too little leaves the problem. Before and after surgery the eye itself is treated with lubricants and a night ointment to protect the cornea, and it may be taped closed at night. If the cause is neurological, treatment turns first to the underlying disease, and surgery is not hurried until the condition has been stable for months. In a newborn whose droop covers the pupil there is no waiting, because the eye learns laziness quickly.'
  },
  seeDoctor: {
    ar: 'اطلب الطوارئ فوراً إذا هبط جفنك فجأةً خلال ساعات أو أيام، وبالأخصّ إن صحبه ازدواج في الرؤية أو اتّساع أو ضيق واضح في بؤبؤ تلك العين أو صداع شديد جديد أو ألم — فقد يكون السبب ضغطاً على عصب من تمدّد في شريان وهي حالة لا تحتمل التأجيل. واذهب أيضاً بسرعة إن تغيّر التدلّي خلال اليوم وزاد مع التعب وصحبه ضعف أو صعوبة في البلع أو النفس. واحجز موعداً عادياً إن كان الجفن يهبط ببطء على مدى سنوات ويعوق نظرك من الأعلى، أو إن كانت الدمعة تفيض على خدّك دائماً، أو إن كنت تحسّ رملاً في عينك ولا يزول مع القطرات، أو ترى رموشك تلامس العين. ولا تؤجّل إن احمرّت العين وضعف بصرها، فالقرنية هي الجزء الذي يدفع الثمن في كل هذه الحالات.',
    en: 'Seek emergency care at once if your lid drops suddenly over hours or days, above all if double vision, a clearly larger or smaller pupil on that side, a severe new headache or pain comes with it, since the cause may be pressure on a nerve from a swelling in an artery, and that cannot be postponed. Go quickly too if the droop varies through the day, worsens with fatigue and comes with weakness or difficulty swallowing or breathing. Book an ordinary appointment if the lid has been sinking slowly over years and blocks your view from above, if tears constantly spill down your cheek, if you feel sand in the eye that drops do not relieve, or if you can see your lashes touching the eye. Do not delay if the eye reddens and its vision weakens, because the cornea is the part that pays the price in all of these.'
  },
  updated: '2026-09-08'
};

DX_BODY['blocked-tear-duct'] = {
  symptoms: {
    ar: 'دمع يفيض على الخدّ بلا بكاء وبلا سبب، يزداد في الهواء والبرد وأمام المكيّف، ويجبر صاحبه على مسح عينه طول اليوم حتى يتسلّخ جلد الخدّ. الرؤية تضبّب ثم تصفو بعد الرمش لأن الدمعة تتجمّع على القرنية. وقد يظهر إفراز لزج يلصق الجفون عند الاستيقاظ، ويحمرّ بياض العين، وتتكرّر التهابات الملتحمة في العين نفسها مرّة بعد مرّة، وهذا التكرار في عين واحدة بالذات هو المفتاح. وعند الضغط على زاوية العين الداخلية قد يخرج سائل أو صديد من فتحة الدمع. وإن التهب كيس الدمع ظهرت كتلة حمراء منتفخة مؤلمة عند تلك الزاوية مع حرارة. وعند الرضّع تكون القصة عيناً دامعة من الأسابيع الأولى مع رمص متكرّر بلا احمرار شديد.',
    en: 'Tears spill onto the cheek without crying and without cause, increasing in wind, in cold and in front of an air conditioner, forcing the person to wipe the eye all day until the skin of the cheek chafes. Vision blurs and then clears after a blink, because tears pool over the cornea. Sticky discharge may appear that glues the lids on waking, the white of the eye reddens, and conjunctivitis recurs in that same eye time after time; this recurrence in one eye in particular is the key. Pressing the inner corner of the eye may bring fluid or pus out of the tear opening. If the tear sac becomes infected, a red, swollen, painful lump appears at that corner with fever. In infants the story is a watering eye from the first weeks with repeated crusting and little redness.'
  },
  cause: {
    ar: 'الدمعة تُفرَز فوق العين وتُكنس بالرمش إلى فتحتين دقيقتين عند الزاوية الداخلية، ثم تسير في قناة إلى كيس صغير ثم تنزل عبر مجرى إلى داخل الأنف، ولهذا يسيل أنف الباكي. فإذا انسدّ أي موضع في هذا الطريق رجعت الدمعة إلى الخارج. وعند الرضّع يكون السبب غشاءً رقيقاً في نهاية المجرى لم ينفتح بعد الولادة، وهو شائع جداً وينفتح وحده عند أكثرهم خلال السنة الأولى. وعند الكبار الأسباب أخرى: تضيّق المجرى مع العمر وهو أكثرها وبالأخصّ عند النساء، والتهابات متكرّرة، وحصاة داخل كيس الدمع، وكسر قديم في عظم الأنف أو الوجه، وجراحة أنف سابقة، وبعض الأدوية والعلاجات، وأمراض الأنف والجيوب المزمنة. وقد يفيض الدمع أيضاً من غير انسداد إطلاقاً، بل من جفاف يهيّج العين فيغرقها الجسم بدمع ردّ فعل، أو من جفن منقلب لا يوصل الدمعة إلى فتحتها.',
    en: 'Tears are made above the eye and swept by blinking into two fine openings at the inner corner, then travel through a duct to a small sac and down a channel into the nose, which is why a crying person sniffs. If anything along that road blocks, the tears back up and spill. In infants the cause is a thin membrane at the end of the channel that has not opened after birth; it is very common and opens by itself in most within the first year. In adults the causes differ: narrowing of the channel with age, the commonest and especially in women; repeated infections; a stone inside the tear sac; an old fracture of the nose or face; previous nasal surgery; certain medicines and treatments; and chronic nasal and sinus disease. Tears may also overflow with no blockage at all, from dryness that irritates the eye so the body floods it with reflex tears, or from a turned lid that never delivers the tear to its opening.'
  },
  diagnosis: {
    ar: 'يبدأ الفحص بما يستبعد الأسباب الأخرى قبل أن يثبت الانسداد: يُنظر إلى وضع الجفن وحافته وفتحة الدمع، ويُصبغ سطح العين ويُقاس ثبات طبقة الدمع، لأن الجفاف يسبّب دمعاً غزيراً ويُعالَج عكس الانسداد تماماً. ثم يُوضع قطرة من صبغة برتقالية في العين ويُنتظر خمس دقائق، فإن بقيت الصبغة في العين ولم تختفِ فالمجرى لا يصرّف. ويُضغط على كيس الدمع فإن رجع إفراز أو صديد فذلك انسداد تحت الكيس. والفحص الحاسم عند الكبار هو غسل المجرى بمحلول عبر أنبوب دقيق: إن وصل المحلول إلى الحلق فالمجرى سالك، وإن رجع فالانسداد كامل. وقد يُصوَّر المجرى بالصبغة أو بالأشعة المقطعية إن كان هناك كسر أو ورم أو حصاة، ويُنظر إلى داخل الأنف بمنظار قبل التخطيط لأي عملية.',
    en: 'The examination begins with what excludes the other causes before it proves a blockage: the position of the lid, its margin and the tear opening are inspected, the surface of the eye is stained and the stability of the tear film measured, because dryness itself causes heavy watering and is treated in the opposite way to a blockage. A drop of orange dye is then placed in the eye and five minutes allowed to pass; if the dye is still sitting there and has not drained, the channel is not clearing. The tear sac is pressed, and if secretion or pus returns, the blockage lies below the sac. The decisive test in adults is washing the channel with fluid through a fine tube: if the fluid reaches the throat the channel is open, and if it comes back the blockage is complete. The channel may be imaged with dye or by CT if there is a fracture, tumour or stone, and the inside of the nose is inspected endoscopically before planning any operation.'
  },
  treatment: {
    ar: 'عند الرضّع الانتظار هو العلاج في أغلب الحالات مع تدليك لطيف يعلّمه الطبيب: ضغط بأصبع نظيف على الزاوية الداخلية للأنف نزولاً عدّة مرّات يومياً، مع تنظيف الجفن بماء دافئ، وأكثرهم يشفى خلال السنة الأولى. فإن استمرّ بعدها فُتح الغشاء بمسبار دقيق في إجراء قصير ونجاحه عالٍ. وعند الكبار يعتمد العلاج على موضع الانسداد ودرجته: قد يكفي توسيع بسيط أو تركيب أنبوب رفيع مؤقّت يبقي المجرى مفتوحاً أشهراً، وقد يحتاج الأمر عملية تفتح طريقاً جديداً من كيس الدمع مباشرة إلى داخل الأنف، وتُجرى إمّا من الجلد أو عبر منظار الأنف بلا أثر خارجي، ونتائجها جيدة عموماً. أما التهاب كيس الدمع الحادّ فيُعالَج أولاً بمضادّ للجراثيم يصفه الطبيب وكمّادات دافئة، ولا تُجرى العملية إلا بعد أن يهدأ الالتهاب.',
    en: 'In infants, waiting is the treatment in most cases, together with gentle massage taught by the doctor: pressing with a clean finger at the inner corner of the nose downward several times a day, with cleaning of the lid using warm water; most recover within the first year. If it persists beyond that, the membrane is opened with a fine probe in a short procedure with a high success rate. In adults treatment depends on where the blockage is and how tight: simple dilation may suffice, or a fine temporary tube left to hold the channel open for months, or an operation may be needed to make a new road from the tear sac directly into the nose, done either through the skin or through a nasal endoscope with no external mark, and its results are generally good. An acute infection of the tear sac is treated first with an antibacterial prescribed by the doctor and warm compresses, and surgery is not performed until the inflammation has settled.'
  },
  seeDoctor: {
    ar: 'اذهب في اليوم نفسه إن ظهرت كتلة حمراء منتفخة مؤلمة عند زاوية العين الداخلية جهة الأنف، خصوصاً مع حرارة أو تورّم يمتدّ إلى الجفن والخدّ، فهذه عدوى في كيس الدمع قد تنتشر إلى المحجر. واحجز موعداً خلال أسابيع إن ظلّ الدمع يفيض على خدّك أشهراً، أو تكرّر التهاب الملتحمة في العين نفسها ثلاث مرّات أو أكثر، أو خرج صديد عند الضغط على الزاوية الداخلية. وعند الرضيع: راجع طبيب الأطفال أو العيون إن استمرّ الدمع بعد إتمام السنة، وفي الحال إن احمرّ الجفن وتورّم أو ارتفعت حرارته أو رفض فتح عينه. ولا تشترِ قطرة مضادّة وتستعملها كل شهر بلا تشخيص، فتكرار الالتهاب في عين واحدة بعينها علامة على مشكلة تصريف لا على عدوى جديدة كل مرّة.',
    en: 'Go the same day if a red, swollen, painful lump appears at the inner corner of the eye towards the nose, especially with fever or swelling spreading to the lid and cheek, because that is an infection of the tear sac that can spread into the orbit. Book an appointment within weeks if tears keep spilling down your cheek for months, if conjunctivitis has recurred in the same eye three times or more, or if pus emerges on pressing the inner corner. For an infant: see the paediatrician or eye doctor if the watering continues past the first birthday, and immediately if the lid reddens and swells, the temperature rises, or the child refuses to open the eye. Do not buy an antibiotic drop and use it every month without a diagnosis, because repeated inflammation in one particular eye is a sign of a drainage problem, not a fresh infection each time.'
  },
  updated: '2026-09-08'
};

DX_BODY['digital-eye-strain'] = {
  symptoms: {
    ar: 'تعب يتراكم مع ساعات الشاشة ويبلغ ذروته آخر النهار: ثقل في العينين ورغبة في إغماضهما، وحرقة ولسعة وإحساس بالجفاف أو بالعكس دمع مفاجئ، واحمرار خفيف. الرؤية تضبّب لحظات ثم تصفو بالرمش، ويصعب على العين أن تنتقل بسرعة من الشاشة إلى بعيد فتبقى الأشياء البعيدة غير واضحة ثوانيَ. ويصحبه صداع حول العينين أو في الجبهة، وألم في الرقبة والكتفين لأن الرأس يميل إلى الأمام لساعات، وحساسية للإضاءة الساطعة. والعلامة المميّزة أن كل هذا يخفّ في العطلة أو بعد يوم بلا شاشة، ويرجع مع أول يوم عمل. وإن استمرّت الشكوى في العطلة وبلا شاشة فالسبب غالباً ليس الشاشة بل شيء آخر يستحقّ فحصاً.',
    en: 'Fatigue that builds through the hours of screen use and peaks at the end of the day: heaviness in the eyes and a wish to close them, burning, stinging and a feeling of dryness or, on the contrary, sudden watering, with mild redness. Vision blurs for moments and then clears with a blink, and the eye struggles to switch quickly from screen to distance, so far objects stay unclear for seconds. Headache around the eyes or across the forehead comes with it, and pain in the neck and shoulders because the head leans forward for hours, along with sensitivity to bright light. The distinguishing mark is that all of this eases during a holiday or after a screen-free day, and returns with the first working day. If the complaint persists on holiday and away from screens, the cause is usually not the screen but something else that deserves examination.'
  },
  cause: {
    ar: 'ثلاثة أشياء تجتمع أمام الشاشة. الأول أن معدّل الرمش يهبط إلى أقلّ من نصفه حين نركّز، ويصير الرمش ناقصاً لا يغلق الجفن تماماً، فتتبخّر طبقة الدمع ويجفّ سطح العين، وهذا أصل الحرقة والاحمرار. والثاني أن عضلة داخل العين تبقى منقبضة ساعات لتثبيت التركيز على مسافة قريبة ثابتة، وعضلات تقريب العينين إلى الداخل تعمل معها بلا راحة، فتشتكي كما تشتكي أي عضلة من ثبات طويل. والثالث ظروف المكان: وهج ينعكس على الشاشة، وتباين ضعيف، وخطّ صغير، وشاشة أعلى من مستوى النظر فتتّسع فتحة العين ويزيد التبخّر، وهواء المكيّف الجافّ. ويكشف كل ذلك عيوباً كانت كامنة: نظارة ناقصة أو غير مصحّحة، أو حَوَل خفيف، أو ضعف في تقارب العينين، أو بداية قصور النظر القريب بعد الأربعين.',
    en: 'Three things come together in front of a screen. First, the blink rate falls to less than half when we concentrate, and blinks become incomplete so the lid never fully closes; the tear film evaporates and the surface of the eye dries, and that is the origin of the burning and redness. Second, a muscle inside the eye stays contracted for hours to hold focus at a fixed near distance, while the muscles that turn the eyes inward work alongside it without rest, so they complain as any muscle does at prolonged fixed effort. Third, the conditions of the place: glare reflected off the screen, poor contrast, small type, a screen set above eye level so the eye opens wider and evaporation increases, and dry air-conditioned air. All of this exposes faults that were hidden: an incorrect or missing prescription, a slight squint, weak convergence, or the beginning of age-related near-focus loss after forty.'
  },
  diagnosis: {
    ar: 'الفحص هنا أهمّ مما يظنّ الناس، لأن نصف الحالات ليست إجهاداً خالصاً بل حالة أخرى ظهرت تحت ضغط الشاشة. يقيس الطبيب النظر للبعيد وللقريب بالمسافة التي تعمل عليها فعلاً لا بمسافة القراءة المعتادة، فيُطلب من المريض أن يذكر بالسنتيمترات كم تبعد شاشته. ويُقاس الانكسار بدقّة بعد إرخاء التركيز، ويُختبر تقارب العينين وقدرتهما على تثبيت الصورة معاً، لأن ضعف التقارب سبب شائع ومعالَج. ويُفحص سطح العين وثبات طبقة الدمع وحافة الجفن بالمصباح الشقّي، ويُقاس ضغط العين ويُفحص قاع العين لاستبعاد أسباب أخرى للصداع وضعف النظر. وإن كان الصداع شديداً أو الشكوى مستمرّة بلا شاشة، بُحث في أسباب عامّة كفقر الدم واضطراب النوم والشقيقة.',
    en: 'Examination matters more here than people think, because half these cases are not pure strain but another condition surfacing under the pressure of the screen. The doctor measures distance and near vision at the working distance actually used rather than the usual reading distance, asking the patient to state in centimetres how far away the screen sits. Refraction is measured precisely after relaxing focus, and the ability of the eyes to converge and hold a single image is tested, since weak convergence is a common and treatable cause. The surface of the eye, the stability of the tear film and the lid margin are examined at the slit lamp, eye pressure measured and the back of the eye inspected to exclude other causes of headache and blurred vision. If the headache is severe or the complaint persists away from screens, general causes such as anaemia, disturbed sleep and migraine are considered.'
  },
  treatment: {
    ar: 'العلاج ترتيب للعادات والمكان قبل أي شيء يوضع في العين. القاعدة العملية المعروفة أن ترفع بصرك كل عشرين دقيقة وتنظر إلى شيء بعيد نحو ستة أمتار مدّة عشرين ثانية، وأن ترمش عمداً رمشاً كاملاً بين الحين والحين، وأن تأخذ وقفة قصيرة كل ساعة تقوم فيها من مكانك. وتُضبط الشاشة: حافتها العليا عند مستوى العين أو أخفض قليلاً، والمسافة نحو ذراع، والخطّ كبير بما يريح، والسطوع مقارباً لسطوع الغرفة لا أشدّ منها، والوهج مُزال بتغيير موضع الشاشة عن النافذة والمصباح. ويصف الطبيب قطرات مرطّبة بلا مواد حافظة عند كثرة الاستعمال، ونظارة بمقاس مخصّص لمسافة الشاشة عند من تجاوز الأربعين، وتمارين تقوية التقارب إن ثبت ضعفه. وترطيب هواء الغرفة وشرب الماء يساعدان، ولا يُغني كل ذلك عن نوم كافٍ.',
    en: 'Treatment is a rearrangement of habits and of the place before anything is put into the eye. The well-known practical rule is to raise your eyes every twenty minutes and look at something about six metres away for twenty seconds, to blink deliberately and completely now and then, and to take a short break every hour in which you stand up. The screen is adjusted: its top edge at or slightly below eye level, the distance about an arm length, the type large enough to be comfortable, the brightness close to that of the room rather than above it, and glare removed by moving the screen away from window and lamp. The doctor prescribes preservative-free lubricating drops where use is frequent, spectacles made for the screen distance in those past forty, and convergence exercises if weakness is proven. Humidifying the room and drinking water help, and none of it replaces enough sleep.'
  },
  seeDoctor: {
    ar: 'راجع طبيب عيون في موعد عادي إن استمرّت الشكوى أكثر من أسابيع رغم ضبط الشاشة والاستراحات، أو إن كنت لا تلبس نظارة ولم تُفحص منذ سنتين، أو تجاوزت الأربعين وبدأت تُبعد الورقة عنك لتقرأ. واذهب أبكر إن صحب الأمر ازدواج في الرؤية أو ألم حقيقي داخل العين لا مجرّد ثقل، أو احمرار مستمرّ مع إفراز، أو صداع يوقظك من النوم أو يزداد مع الانحناء أو يصحبه غثيان. وراجع فوراً إن هبط بصرك في عين واحدة أو رأيت ومضات أو عوّامات جديدة أو ظلاً في مجال النظر، فهذي ليست من إجهاد الشاشة في شيء. وعند الطفل الذي يشكو صداعاً يومياً بعد الدراسة أو يقرّب وجهه من الشاشة أو يغمض عيناً ليركّز، فالفحص لا يُؤجّل إلى نهاية العام الدراسي.',
    en: 'See an ophthalmologist at an ordinary appointment if the complaint lasts more than a few weeks despite adjusting the screen and taking breaks, if you wear no glasses and have not been examined for two years, or if you are past forty and have begun holding the page further away to read. Go sooner if double vision comes with it, or real pain inside the eye rather than mere heaviness, or persistent redness with discharge, or a headache that wakes you from sleep, worsens on bending, or comes with nausea. Go at once if vision drops in one eye, or you see new flashes, floaters or a shadow in the field of view, because none of these belongs to screen strain. For a child complaining of daily headaches after schoolwork, bringing his face close to the screen, or closing one eye to concentrate, the examination should not be put off until the end of the school year.'
  },
  updated: '2026-09-08'
};

/* ==================== الأذن والسمع والتوازن ==================== */

DX_BODY['sudden-hearing-loss'] = {
  symptoms: {
    ar: 'يستيقظ الإنسان فيجد أذناً واحدة كأنها مسدودة بقطنة، أو يحسّ وهو يتكلّم في الهاتف أن الصوت لا يصل من تلك الجهة. والهبوط يقع خلال ساعات أو خلال ثلاثة أيام على الأكثر، وغالباً بلا أي ألم وبلا رشح وبلا إفراز، ولهذا يُظنّ شمعاً أو ماء بقي بعد الاستحمام أو أثر زكام. ويصحبه في أكثر الحالات طنين جديد يبدأ مع الهبوط نفسه، وإحساس بامتلاء وضغط داخل الأذن، وقد يأتي معه دوار أو عدم اتزان خفيف. والأصوات المسموعة تتشوّه فتبدو معدنية أو مبحوحة أو بطبقة مختلفة عن الأذن الأخرى، ويصعب فهم الكلام في الضجيج حتى ما يُسمع منه. وأخطر ما في الأعراض أنها غير مؤلمة إطلاقاً، فيقرّر صاحبها أن ينتظر أسبوعاً ليرى.',
    en: 'A person wakes to find one ear as if plugged with cotton, or notices while speaking on the phone that sound does not come through on that side. The loss happens over hours, or at most over three days, usually with no pain, no cold and no discharge, which is why it is put down to wax, to water left after a shower, or to the after-effect of a cold. In most cases a new ringing begins at the same moment as the loss, with a sense of fullness and pressure inside the ear, and mild dizziness or unsteadiness may come with it. Sounds that are still heard become distorted, sounding metallic, hoarse or at a different pitch from the other ear, and speech is hard to follow in noise even when audible. The most dangerous feature of all is that it does not hurt at all, so the sufferer decides to wait a week and see.'
  },
  cause: {
    ar: 'الخلايا الشعرية داخل القوقعة دقيقة جداً وتعتمد على شريان واحد رفيع لا بديل له، فأي إصابة تصلها تضرّها بسرعة. وفي أكثر الحالات لا يُعرف السبب بيقين، والفرضيات الراجحة ثلاث: التهاب فيروسي أصاب العصب أو القوقعة، أو اضطراب في الدورة الدموية الدقيقة داخل الأذن الداخلية، أو تفاعل مناعي يهاجم الأذن. وهناك أسباب تُبحث لأنها تُعالَج بطريقة مختلفة تماماً: ورم حميد على عصب السمع، ومرض مناعي جهازي، وتمزّق غشاء بين الأذن الوسطى والداخلية بعد مجهود أو غطس أو سفر جوي، وتصلّب متعدّد، وإصابة رأس، وبعض الأدوية السامّة للأذن، والتهاب السحايا، وأمراض الدم. والمهمّ أن أي أذن هبط سمعها فجأةً تُعامَل معاملة الحالة العاجلة قبل أن يُعرف سببها.',
    en: 'The hair cells inside the cochlea are extremely delicate and depend on a single fine artery with no alternative, so any insult that reaches them harms them quickly. In most cases no cause is known for certain, and three explanations are favoured: a viral inflammation of the nerve or the cochlea, a disturbance of the tiny circulation inside the inner ear, or an immune reaction attacking the ear. Some causes are actively sought because they are treated quite differently: a benign tumour on the hearing nerve, a systemic immune disease, a tear in the membrane between the middle and inner ear after straining, diving or air travel, multiple sclerosis, head injury, certain medicines toxic to the ear, meningitis and blood disorders. What matters is that any ear whose hearing has dropped suddenly is treated as urgent before its cause is known.'
  },
  diagnosis: {
    ar: 'أول خطوة أن يُنظر داخل الأذن، فإن كانت القناة نظيفة والطبلة سليمة فالمشكلة ليست انسداداً بل داخل الأذن أو في العصب، وهذا وحده يقلب الأمر من شكوى عادية إلى حالة عاجلة. ويُجرى فحص بسيط بالشوكة الرنّانة عند السرير يفرّق بين ضعف سمع سببه انسداد وضعف سببه العصب، ويمكن لأي طبيب عام أن يفعله. والفحص المعياري هو قياس السمع بالجهاز في غرفة عازلة: يرسم منحنى السمع لكل أذن على الترددات، ويثبت هل الضعف حسّي عصبي وكم مقداره، وهو ما يقرّر العلاج ويُقاس عليه التحسّن لاحقاً. ويُطلب رنين مغناطيسي للأذن والدماغ بالصبغة لاستبعاد ورم على عصب السمع أو آفة في الدماغ، ولا يُنتظر نتيجته لبدء العلاج. وتُسحب تحاليل دم بحسب ما يشتبه به الطبيب.',
    en: 'The first step is to look inside the ear, and if the canal is clear and the drum intact, the problem is not a blockage but lies within the inner ear or the nerve, and that alone turns an ordinary complaint into an urgent one. A simple tuning fork test at the bedside distinguishes a loss caused by blockage from one caused by the nerve, and any general practitioner can perform it. The standard test is audiometry in a sound-treated room: it plots the hearing curve of each ear across the frequencies, establishes whether the loss is sensorineural and how large it is, and it is what decides treatment and against which later improvement is measured. Magnetic resonance imaging of the ear and brain with contrast is requested to exclude a tumour on the hearing nerve or a lesion in the brain, and treatment is not delayed while awaiting its result. Blood tests are taken according to what the doctor suspects.'
  },
  treatment: {
    ar: 'نافذة العلاج قصيرة جداً: أفضل النتائج لمن بدأ خلال الأيام الأولى، والفرصة تتضاءل كلما مرّ الوقت حتى تكاد تُغلق بعد أسابيع. والعلاج الأساسي جرعات من مضادّ التهاب قويّ يبدأها الطبيب بسرعة، إمّا عن طريق الفم أو بحقنه مباشرة داخل الأذن الوسطى عبر الطبلة في العيادة، وهذي الطريقة الأخيرة توصل الدواء إلى الأذن الداخلية بتركيز أعلى وتفيد بالذات من عنده سكري أو ضغط يمنعه من الجرعات الفموية العالية. وقد يُجمع بين الطريقتين في الحالات الشديدة. ويُضاف علاج السبب إن وُجد سبب. ويُعاد قياس السمع بعد أسبوعين لقياس الاستجابة. ونصف المرضى تقريباً يتحسّنون، وبعضهم يعود سمعه كاملاً، ومن بقي عنده نقص دائم تُناقَش معه المعينات السمعية أو الزراعة لاحقاً. والصدق مطلوب: العلاج المبكر يرفع الفرصة ولا يضمنها.',
    en: 'The treatment window is very short: the best results belong to those who start within the first days, and the chance dwindles as time passes until it is nearly closed after some weeks. The mainstay is a course of a strong anti-inflammatory begun quickly by the doctor, either by mouth or injected directly into the middle ear through the drum in the clinic; this last route delivers a higher concentration to the inner ear and particularly suits those whose diabetes or blood pressure prevents high oral doses. The two routes may be combined in severe cases. Treatment of the cause is added where a cause is found. Hearing is measured again after two weeks to judge the response. About half of patients improve and some recover fully; those left with a permanent loss discuss hearing aids or implantation later. Honesty is required: early treatment raises the chance without guaranteeing it.'
  },
  seeDoctor: {
    ar: 'هذه حالة تُقاس بالساعات لا بالأسابيع: اذهب إلى الطوارئ أو إلى طبيب أنف وأذن في اليوم نفسه إذا هبط سمع أذن واحدة فجأةً بلا سبب واضح، ولو كان معك زكام، ولو ظننتها شمعاً، ولو لم تؤلمك إطلاقاً. ولا تنتظر موعداً بعد أسبوع ولا تجرّب قطرات في البيت ولا تحاول شفط الأذن أو تنظيفها. واطلب صراحةً أن يُنظر داخل أذنك وأن يُجرى لك قياس سمع، وإن قيل لك إنها شمع فتأكّد أن السمع رجع بعد إزالته فعلاً. واطلب الإسعاف فوراً إن صحب هبوط السمع دوار شديد لا تستطيع معه الوقوف، أو ازدواج رؤية، أو ضعف أو تنميل في الوجه أو الأطراف، أو تلعثم في الكلام، أو صداع شديد جديد. والأهل والأصدقاء يشاركون في هذا: من قال لك إن أذنه صارت لا تسمع منذ اليوم فخذه اليوم لا غداً.',
    en: 'This is a condition measured in hours, not weeks: go to an emergency department or an ear, nose and throat doctor the same day if the hearing of one ear drops suddenly without clear cause, even if you have a cold, even if you assume it is wax, and even if it does not hurt at all. Do not wait for an appointment a week away, do not try drops at home, and do not attempt to suction or clean the ear. Ask explicitly for the ear to be looked into and for a hearing test, and if you are told it is wax, make sure the hearing truly returned after it was removed. Call an ambulance at once if the hearing loss comes with vertigo so severe you cannot stand, double vision, weakness or numbness of the face or limbs, slurred speech, or a severe new headache. Family and friends share in this: whoever tells you his ear stopped hearing today should be taken today, not tomorrow.'
  },
  updated: '2026-09-08'
};

DX_BODY['otitis-externa'] = {
  symptoms: {
    ar: 'ألم في الأذن يبدأ حكّة وامتلاءً ثم يشتدّ حتى يمنع النوم، وميزته أنه يزداد زيادة واضحة عند شدّ صيوان الأذن إلى الخلف أو الضغط على النتوء الصغير أمام فتحتها، وعند المضغ أحياناً. وهذه العلامة بالذات هي التي تفرّقه عن التهاب الأذن الوسطى الذي لا يؤلمه شدّ الصيوان. وتتورّم القناة حتى تضيق فيهبط السمع ويصير الصوت مكتوماً كأن الأذن مسدودة، ويخرج إفراز رقيق أو سميك أبيض أو مصفرّ له رائحة، وقد يتقشّر الجلد حول الفتحة. والقصة غالباً واضحة: سباحة أو غوص أو استحمام طويل قبل أيام، أو تنظيف بعود قطن أو دبّوس، أو سمّاعة أذن تُلبس ساعات طويلة. وعند اشتداده يمتدّ التورّم إلى ما حول الأذن ويصعب فتح الفم.',
    en: 'Ear pain that begins as itching and fullness and then sharpens until it prevents sleep, marked by clearly worsening when the outer ear is pulled backwards or the little prominence in front of the opening is pressed, and sometimes on chewing. That sign in particular separates it from middle ear infection, in which pulling the outer ear does not hurt. The canal swells until it narrows, so hearing drops and sound becomes muffled as though the ear were plugged; a thin or thick white or yellowish discharge with an odour appears, and the skin around the opening may flake. The story is usually clear: swimming, diving or a long shower some days earlier, cleaning with a cotton bud or a pin, or an earpiece worn for long hours. As it worsens, swelling spreads around the ear and opening the mouth becomes difficult.'
  },
  cause: {
    ar: 'جلد قناة الأذن رقيق جداً وتحته عظم مباشرة، ويحميه غشاء حمضي رقيق وشمع الأذن نفسه الذي يطرد الماء والجراثيم. فإذا بقي الماء في القناة بعد السباحة أو الاستحمام تغيّر هذا الوسط وانتفخ الجلد ولان، وصار مرتعاً للجراثيم التي تعيش في الماء الدافئ. وإذا نُظّفت الأذن بعود قطن أُزيل الشمع الواقي وخُدش الجلد فدخلت الجراثيم من الخدش، ولهذا يكثر المرض عند من ينظّف أذنيه كثيراً لا عند من يهملهما. ويهيّئ له أيضاً كلّ ما يسدّ القناة أو يبلّها: سمّاعات الأذن الداخلية، والمعينات السمعية، وسدادات السباحة، والرطوبة العالية والحرّ، وأمراض الجلد كالإكزيما والصدفية التي تجعل الجلد متقشّراً هشّاً. ومرضى السكري وضعاف المناعة معرّضون لصورة أشدّ تمتدّ إلى العظم وهي خطيرة.',
    en: 'The skin of the ear canal is very thin with bone directly beneath it, protected by a thin acidic film and by earwax itself, which repels water and germs. If water stays in the canal after swimming or bathing, that environment changes and the skin swells and softens, becoming a bed for the germs that live in warm water. If the ear is cleaned with a cotton bud, the protective wax is removed and the skin scratched, so germs enter through the scratch, which is why the illness is common in those who clean their ears often rather than those who leave them alone. Anything that blocks or wets the canal also predisposes: in-ear headphones, hearing aids, swimming plugs, high humidity and heat, and skin diseases such as eczema and psoriasis that leave the skin flaky and fragile. People with diabetes and weakened immunity are prone to a severer form that spreads into the bone and is dangerous.'
  },
  diagnosis: {
    ar: 'التشخيص بالنظر والقصّة، ولا يحتاج تحاليل في الحالات المعتادة: يشدّ الطبيب الصيوان فيتألّم المريض، ثم ينظر بالمنظار الضوئي فيرى قناة حمراء متورّمة ضيّقة فيها إفراز أو قشور أو ما يشبه قطناً رطباً، وقد تكون ضيّقة إلى حدّ لا تُرى معه الطبلة. ورؤية الطبلة مهمّة لأن سلامتها تحدّد العلاج: بعض القطرات لا تُستعمل مع طبلة مثقوبة. وإن كانت القناة مسدودة تماماً بالتورّم فقد يضع الطبيب فتيلة رفيعة تحمل الدواء إلى العمق. وتُؤخذ مسحة للزرع إن تكرّر الالتهاب أو لم يستجب أو كان المريض سكرياً، ويُشكّ في الفطريات إن رأى الطبيب خيوطاً بيضاء أو سوداء تشبه ورق النشّاف. وعند مريض السكري بألم شديد ليلي وتورّم ممتدّ يُصوَّر العظم بحثاً عن امتداد الالتهاب إليه.',
    en: 'Diagnosis is by inspection and history and needs no tests in ordinary cases: the doctor pulls the outer ear, which hurts, then looks with an otoscope and sees a red, swollen, narrowed canal containing discharge, crusts or what looks like wet cotton, sometimes so narrow that the drum cannot be seen. Seeing the drum matters, because its integrity decides the treatment: some drops are not used with a perforated drum. If the canal is completely closed by swelling, the doctor may place a fine wick to carry the medicine to the depth. A swab is cultured if the infection recurs, fails to respond, or the patient has diabetes, and fungus is suspected if the doctor sees white or black threads resembling blotting paper. In a diabetic patient with severe night pain and spreading swelling, the bone is imaged to look for extension of the infection into it.'
  },
  treatment: {
    ar: 'الأساس قطرات موضعية يصفها الطبيب حسب ما يراه، ومعها مسكّن للألم لأن الألم هنا شديد فعلاً ويستحقّ علاجاً جادّاً في الأيام الأولى. والأهمّ في نجاح القطرة أمران يهملهما أكثر الناس: أن تُنظَّف القناة أولاً من الإفراز والقشور عند الطبيب وإلا لم يصل الدواء إلى الجلد، وأن تُقطَّر بطريقة صحيحة بأن يستلقي المريض على جنبه والأذن المصابة إلى الأعلى ويبقى كذلك عدّة دقائق ويُحرَّك النتوء الأمامي ليدخل الدواء. وتُبقى الأذن جافّة تماماً طوال العلاج: لا سباحة ولا غطس، وتُحمى عند الاستحمام بقطنة مدهونة بالفازلين. ولا تُستعمل أعواد القطن مطلقاً. والمضادّ الحيوي بالفم لا يُعطى في الحالة البسيطة لأنه لا يصل إلى جلد القناة جيداً، ويُحفَظ لمن امتدّ عنده الالتهاب أو كان مريض سكري أو ضعيف المناعة.',
    en: 'The mainstay is topical drops chosen by the doctor, together with pain relief, because the pain here is genuinely severe and deserves serious treatment in the first days. Two things decide whether the drops work, and most people neglect both: the canal must first be cleaned of discharge and crusts by the doctor, or the medicine never reaches the skin; and the drops must be instilled correctly, with the patient lying on his side, affected ear uppermost, staying so for several minutes while the front prominence is moved to let the drops down. The ear is kept completely dry throughout: no swimming, no diving, and protection while showering with cotton smeared with petroleum jelly. Cotton buds are not used at all. Oral antibiotics are not given in a simple case, since they reach the canal skin poorly, and are reserved for spreading infection, diabetes or weakened immunity.'
  },
  seeDoctor: {
    ar: 'راجع الطبيب خلال يوم أو يومين إن أوجعتك أذنك ألماً يزداد بشدّ الصيوان، أو خرج منها إفراز، أو هبط سمعك، ولا تعالجها بقطرة قديمة في البيت لأن القطرة الخاطئة على طبلة مثقوبة تضرّ. واذهب إلى الطوارئ في اليوم نفسه إذا امتدّ التورّم والاحمرار إلى ما خلف الأذن أو إلى الوجه والرقبة، أو دُفع الصيوان إلى الأمام، أو ارتفعت حرارتك، أو صار فتح فمك صعباً، أو ظهر ضعف في عضلات الوجه بجهة الأذن، أو صحب الألم دوار شديد. ولمريض السكري أو ضعيف المناعة قاعدة خاصة: ألم أذن شديد يوقظك ليلاً ولا يستجيب للعلاج خلال أيام يستحقّ مراجعة عاجلة ولو بدت الأذن غير مخيفة، فامتداد الالتهاب إلى العظم يبدأ هكذا بالضبط.',
    en: 'See a doctor within a day or two if your ear hurts with pain that worsens on pulling the outer ear, if discharge appears, or if hearing drops, and do not treat it with an old drop at home, because the wrong drop on a perforated drum does harm. Go to the emergency department the same day if swelling and redness spread behind the ear or into the face and neck, if the outer ear is pushed forward, if your temperature rises, if opening your mouth becomes difficult, if weakness appears in the facial muscles on that side, or if the pain comes with severe vertigo. People with diabetes or weakened immunity have a rule of their own: severe ear pain that wakes you at night and does not respond within days deserves urgent review even if the ear does not look alarming, because spread of infection into the bone begins exactly like that.'
  },
  updated: '2026-09-08'
};

DX_BODY['earwax-impaction'] = {
  symptoms: {
    ar: 'إحساس بامتلاء وضغط داخل الأذن، وسمع يهبط في تلك الأذن هبوطاً واضحاً، وغالباً يقع فجأةً بعد استحمام أو سباحة لأن الماء ينفخ الشمع فيسدّ ما بقي من المجرى. وقد يظهر طنين أو صوت يشبه الحفيف، وتُسمع أصوات الجسم نفسه عالية كصوت المضغ أو النَفَس. ويشكو بعضهم من حكّة أو سعال جافّ غريب لأن عصباً في قناة الأذن يشترك مع الحلق. والألم قليل عادةً إلا إن ضغط الشمع الصلب على الجلد أو الطبلة فيصير هناك وجع مزعج. وقد تظهر دوخة خفيفة أو عدم اتزان. والعلامة الفارقة أن السمع يرجع فوراً وكاملاً بعد إزالة السدادة، وإن لم يرجع فالمشكلة لم تكن الشمع أصلاً وهذا ما يجب التنبّه له.',
    en: 'A feeling of fullness and pressure inside the ear, with a clear drop in hearing on that side, often occurring suddenly after a shower or a swim because water swells the wax and closes what was left of the passage. Ringing or a rustling sound may appear, and the body own sounds, such as chewing or breathing, are heard loudly. Some complain of itching or an odd dry cough, because a nerve in the ear canal shares with the throat. Pain is usually slight, unless hard wax presses on the skin or the drum, when a nagging ache appears. Mild dizziness or unsteadiness may occur. The distinguishing sign is that hearing returns immediately and fully once the plug is removed; if it does not return, the problem was never the wax, and that is what must be noticed.'
  },
  cause: {
    ar: 'شمع الأذن ليس وسخاً بل إفراز واقٍ يمنع الماء والجراثيم ويحمل معه القشور والغبار خارجاً، والقناة تنظّف نفسها ذاتياً بحركة الجلد نحو الفتحة، ولهذا فالأذن السليمة لا تحتاج تنظيفاً إطلاقاً. والانحشار يحدث حين يُدفع الشمع إلى الداخل بدل أن يخرج، وأكبر أسبابه على الإطلاق عود القطن الذي يخرج بقليل منه ويكبس الباقي أمام الطبلة. ويليه كل ما يسدّ القناة ساعات طويلة: سمّاعات الأذن الداخلية، والمعينات السمعية، وسدادات النوم والسباحة. ويكثر أيضاً عند من قناته ضيّقة أو ملتوية أو كثيرة الشعر، وعند كبار السنّ لأن الشمع يجفّ ويقسو مع العمر وتضعف حركة الجلد الذاتية، وعند أصحاب الإكزيما والصدفية لكثرة القشور، وعند من يستعمل شمعة الأذن المتداولة فهي عديمة الفائدة وتُحدث حروقاً وانسدادات.',
    en: 'Earwax is not dirt but a protective secretion that keeps out water and germs and carries flakes and dust outward, and the canal cleans itself by a movement of the skin towards the opening, so a healthy ear needs no cleaning at all. Impaction happens when wax is pushed inward instead of out, and by far the biggest cause is the cotton bud, which brings a little out and packs the rest against the drum. Next comes anything that blocks the canal for long hours: in-ear headphones, hearing aids, and sleeping or swimming plugs. It is also common in those whose canal is narrow, curved or hairy; in older people, because wax dries and hardens with age and the skin self-cleaning slows; in people with eczema and psoriasis because of the flaking; and in users of ear candles, which are useless and cause burns and blockages.'
  },
  diagnosis: {
    ar: 'ينظر الطبيب بالمنظار الضوئي فيرى السدادة ولونها وقوامها وهل تسدّ المجرى كلياً أم جزئياً، وهذا يكفي للتشخيص. والمهمّ في الفحص ليس رؤية الشمع بل ما تحته: هل الطبلة سليمة أم مثقوبة، لأن ذلك يمنع طريقة إزالة ويجيز أخرى. ويسأل الطبيب عن عمليات سابقة في الأذن وعن أنبوب تهوية مركّب، وعن السكري وضعف المناعة، لأن الغسل قد لا يناسبهم. وبعد الإزالة يُعاد النظر إلى الطبلة والقناة ويُختبر السمع ولو بالهمس أو بالشوكة الرنّانة. وهذا الاختبار البعدي هو الخطوة التي لا يجوز إهمالها: إن بقي السمع ناقصاً بعد إزالة كاملة للشمع فالسبب في مكان آخر، وقد يكون سائلاً خلف الطبلة أو ضعفاً حسّياً عصبياً يحتاج قياس سمع وربما علاجاً عاجلاً.',
    en: 'The doctor looks with an otoscope and sees the plug, its colour and consistency and whether it blocks the passage wholly or partly, and that suffices for the diagnosis. What matters in the examination is not seeing the wax but what lies beneath it: whether the drum is intact or perforated, since that forbids one method of removal and permits another. The doctor asks about previous ear operations and any ventilation tube, and about diabetes and weakened immunity, for whom syringing may be unsuitable. After removal the drum and canal are inspected again and hearing tested, if only by whisper or tuning fork. This after-check is the step that must never be skipped: if hearing remains reduced once the wax is completely gone, the cause lies elsewhere, perhaps fluid behind the drum or a sensorineural loss needing audiometry and possibly urgent treatment.'
  },
  treatment: {
    ar: 'أبسط ما يُبدأ به قطرات مليّنة توضع في الأذن أياماً قليلة لتفتّت الشمع وتليّنه، وكثير من السدادات تخرج وحدها بعدها. فإن لم تخرج فالإزالة عند مختصّ بثلاث طرق: الشفط بجهاز رفيع تحت الرؤية المباشرة وهي الأنظف وتُفضَّل عند وجود ثقب أو أنبوب، أو الإخراج بأداة دقيقة مخصّصة، أو الغسل بماء بدرجة حرارة الجسم بضغط لطيف بعد تليين مسبق. والغسل ممنوع مع طبلة مثقوبة أو أنبوب تهوية أو عملية أذن سابقة أو التهاب نشط، وقد لا يُنصح به لمريض السكري. أما في البيت فلا تُدخل الأذن أعواد قطن ولا دبابيس ولا مفاتيح ولا شمعة الأذن، فالشمعة عديمة الفائدة ومصدر حروق وانسدادات مثبتة. ومن يتكرّر عنده الانحشار يستفيد من تليين دوري بإشراف طبيبه ومن التقليل من سدّ الأذن بالسمّاعات.',
    en: 'The simplest starting point is softening drops placed in the ear for a few days to break up and soften the wax, after which many plugs come out on their own. If they do not, removal by a specialist takes three forms: suction with a fine device under direct vision, which is the cleanest and preferred where there is a perforation or a tube; extraction with a fine purpose-made instrument; or irrigation with water at body temperature at gentle pressure after prior softening. Irrigation is forbidden with a perforated drum, a ventilation tube, previous ear surgery or active infection, and may be inadvisable in diabetes. At home, nothing is put into the ear: no cotton buds, pins or keys, and no ear candle, which is useless and a proven source of burns and blockages. Anyone with repeated impaction benefits from periodic softening under their doctor supervision and from blocking the ear less with earphones.'
  },
  seeDoctor: {
    ar: 'راجع طبيباً في موعد قريب إن أحسست بانسداد وهبوط سمع في أذن واحدة ولم يزل خلال أيام، أو إن كنت لا ترى ما بداخلها ولا تعرف إن كان شمعاً. واذهب في اليوم نفسه إن صحب الأمر ألم شديد أو إفراز أو حرارة أو دوار. والقاعدة التي تنقذ سمعاً: إن أُزيل الشمع كاملاً وبقي السمع ناقصاً في تلك الأذن فلا ترضَ بجواب أن السبب كان الشمع — اطلب قياس سمع فوراً، لأن فقدان السمع المفاجئ الحسّي العصبي يُشخَّص خطأً كشمع كثيراً، ونافذة علاجه أيام معدودة. ولا تحاول إزالة الشمع بنفسك بأي أداة ولا تستعمل شمعة الأذن. ومن عنده طبلة مثقوبة أو أنبوب تهوية أو عملية أذن سابقة فليقل ذلك قبل أن يُغسَل، فالماء قد يدخل إلى الأذن الوسطى ويسبّب التهاباً ودواراً.',
    en: 'See a doctor at an early appointment if you feel blockage and reduced hearing in one ear that has not cleared within days, or if you cannot see inside and do not know whether it is wax. Go the same day if severe pain, discharge, fever or vertigo comes with it. Here is the rule that saves hearing: if the wax has been removed completely and the hearing in that ear is still reduced, do not accept the answer that wax was the cause. Ask for a hearing test at once, because sudden sensorineural hearing loss is often misdiagnosed as wax and its treatment window is only a few days. Do not try to remove wax yourself with any instrument and do not use an ear candle. Anyone with a perforated drum, a ventilation tube or previous ear surgery should say so before any syringing, since water may enter the middle ear and cause infection and vertigo.'
  },
  updated: '2026-09-08'
};

DX_BODY['tympanic-perforation'] = {
  symptoms: {
    ar: 'كثيراً ما تبدأ القصّة بألم شديد في الأذن يبلغ ذروته ثم يزول فجأةً في اللحظة نفسها التي يسيل فيها سائل أو صديد أو دم من الأذن، وهذا الارتياح المفاجئ بعد الألم هو أوضح علامة على أن الطبلة انفتحت وخرج ما كان محبوساً خلفها. ويهبط السمع في تلك الأذن هبوطاً متوسّطاً ويصير الصوت مكتوماً، ويظهر طنين، وقد تأتي دوخة خفيفة. وبعد استقرار الحال تبقى الشكوى الأهمّ: الأذن لا تحتمل الماء إطلاقاً، فكل استحمام أو سباحة يعقبه ألم وإفراز والتهاب جديد. ومن ثُقبت طبلته بضربة أو انفجار قريب يشكو طنيناً حادّاً وسمعاً مكتوماً في الحال. وقد يمرّ ثقب صغير بلا أي عرض ويُكتشف مصادفةً في فحص عابر.',
    en: 'The story often begins with severe ear pain that reaches its peak and then vanishes suddenly at the very moment fluid, pus or blood runs from the ear, and that abrupt relief after pain is the clearest sign that the drum has opened and released what was trapped behind it. Hearing in that ear falls moderately and sound becomes muffled, ringing appears, and mild dizziness may follow. Once things settle, the most important complaint remains: the ear cannot tolerate water at all, so every shower or swim is followed by pain, discharge and fresh infection. Someone whose drum was perforated by a blow or a nearby blast complains of sharp ringing and muffled hearing at once. A small perforation may pass with no symptom at all and be found by chance at a routine examination.'
  },
  cause: {
    ar: 'الطبلة غشاء رقيق مشدود يفصل قناة الأذن عن الأذن الوسطى وينقل الاهتزاز إلى العُظيمات، وهو رقيق بطبيعته فيُخرَق بأسباب متعدّدة. أشيعها التهاب الأذن الوسطى الحادّ حين يتجمّع الصديد خلفه ويرتفع الضغط حتى يمزّقه. ويليه الأذى المباشر: عود قطن أو دبّوس أو مفتاح يُدفع في الأذن، وهذا يقع كثيراً أثناء التنظيف. ثم إصابات الضغط: صفعة على الأذن، وانفجار قريب، وغطس أو نزول طائرة بأذن مسدودة لا تتوازن. وقد يحدث الثقب بعد سقوط أو كسر في عظم الجمجمة، أو بعد إدخال أنبوب تهوية يترك ثقباً لا يلتئم عند خروجه، أو من التهاب مزمن يأكل الغشاء ببطء. ويزيد احتمال الثقب في الأذن التي تتكرّر التهاباتها منذ الطفولة أو التي تعاني ضعف تهوية عبر قناة أوستاش.',
    en: 'The eardrum is a thin, taut membrane separating the ear canal from the middle ear and passing vibration to the small bones; being thin by nature, it is torn by several causes. The commonest is acute middle ear infection, when pus gathers behind it and pressure rises until it bursts. Next comes direct injury: a cotton bud, pin or key pushed into the ear, which often happens during cleaning. Then pressure injuries: a slap on the ear, a nearby explosion, and diving or aircraft descent with a blocked ear that cannot equalise. Perforation may also follow a fall or a skull fracture, or the removal of a ventilation tube that leaves a hole which does not close, or a chronic infection that slowly eats the membrane. The risk rises in an ear with repeated infections since childhood or with poor ventilation through the eustachian tube.'
  },
  diagnosis: {
    ar: 'النظر بالمنظار الضوئي يكفي في أكثر الحالات: يرى الطبيب الثقب ويحدّد حجمه وموضعه من الطبلة، والموضع مهمّ لأن ثقوب الجزء العلوي الخلفي أخطر وتستدعي انتباهاً لاحتمال نمو جلد داخل الأذن الوسطى. ويُنظّف الإفراز أولاً لتُرى الطبلة، وقد يُستعمل مجهر أو منظار مكبّر. ويُقاس السمع بجهاز القياس ليُعرف مقدار الفقد وهل هو انسدادي فقط أم معه ضعف حسّي عصبي يدلّ على أذى وصل إلى الأذن الداخلية. ويُجرى فحص يقيس مرونة الطبلة وضغط الأذن الوسطى، وفي الثقب يعطي منحنى مسطّحاً مع حجم قناة كبير وهذا يؤكّد وجود فتحة. وتُؤخذ مسحة للزرع إن كان الإفراز مستمرّاً، وتُطلب أشعة مقطعية للعظم إن اشتُبه في التهاب مزمن أو تلف في العُظيمات أو نمو نسيج غير طبيعي.',
    en: 'Otoscopy suffices in most cases: the doctor sees the hole and notes its size and its position on the drum, and the position matters because holes in the upper posterior part are more serious and call for vigilance about skin growing into the middle ear. Discharge is cleaned first so the drum can be seen, and a microscope or magnifying endoscope may be used. Hearing is measured with an audiometer to learn the size of the loss and whether it is purely conductive or accompanied by a sensorineural component indicating harm that reached the inner ear. A test measuring the mobility of the drum and middle ear pressure is performed, and with a perforation it gives a flat trace with a large canal volume, confirming an opening. A swab is cultured if discharge persists, and a CT of the bone is requested if chronic infection, damage to the small bones or abnormal tissue growth is suspected.'
  },
  treatment: {
    ar: 'أكثر الثقوب الصغيرة الناتجة عن التهاب أو إصابة تلتئم وحدها خلال أسابيع قليلة إن حُفظت الأذن جافّة ونظيفة، والانتظار المراقَب هو العلاج المعقول في البداية. والقاعدة الذهبية: لا يدخل الأذن ماء ولا قطرة ولا أي شيء إلا بأمر الطبيب، لأن بعض القطرات تضرّ الأذن الداخلية إذا نزلت عبر ثقب. ويُحمى الأذن عند الاستحمام بقطنة مدهونة بالفازلين، وتُمنع السباحة والغطس، ويُنصح بتجنّب نفخ الأنف بقوّة. وإن ظهر التهاب أو إفراز فالعلاج بقطرة يختارها الطبيب لأنها آمنة مع الثقب، وأحياناً علاج بالفم. وإن بقي الثقب مفتوحاً أشهراً أو تكرّرت الالتهابات أو أزعج فقدان السمع أو كان صاحبه يسبح أو يغوص، فترقيع الطبلة عملية معروفة ناجحة تُجرى بأخذ نسيج من المريض نفسه ووضعه مكان الفتحة.',
    en: 'Most small perforations caused by infection or injury heal on their own within a few weeks if the ear is kept dry and clean, and watchful waiting is the reasonable first course. The golden rule: nothing enters the ear, no water, no drop and nothing else, except on the doctor instruction, because some drops harm the inner ear if they pass through a hole. The ear is protected while showering with cotton smeared with petroleum jelly, swimming and diving are stopped, and forceful nose-blowing is discouraged. If infection or discharge appears, treatment is a drop the doctor selects as safe with a perforation, and sometimes medicine by mouth. If the hole stays open for months, if infections recur, if the hearing loss is troublesome, or if the person swims or dives, repairing the drum is a well-established and successful operation performed by taking tissue from the patient himself and laying it over the opening.'
  },
  seeDoctor: {
    ar: 'راجع طبيب أنف وأذن خلال أيام إن سال من أذنك سائل أو دم بعد ألم، أو هبط سمعك بعد ضربة أو غطس أو دخول عود في الأذن، أو بقيت الأذن تسيل أكثر من أسبوعين. واذهب إلى الطوارئ في الحال إن صحب ذلك دوار شديد أو قيء أو تلعثم، أو ضعف في نصف الوجه من جهة الأذن، أو صداع شديد وحرارة وتصلّب في الرقبة، أو تورّم واحمرار خلف الأذن يدفع الصيوان إلى الأمام، أو كان سبب الثقب إصابة رأس مع خروج سائل صافٍ. ولا تضع أي قطرة في أذن تسيل قبل أن يراها طبيب. واحرص على الجفاف التامّ حتى يقول لك الطبيب إن الطبلة أُغلقت، فالسباحة بأذن مثقوبة سبب متكرّر لالتهاب مزمن يصعب علاجه لاحقاً.',
    en: 'See an ear, nose and throat doctor within days if fluid or blood has run from your ear after pain, if your hearing dropped after a blow, a dive or a bud pushed into the ear, or if the ear keeps discharging for more than two weeks. Go to the emergency department at once if severe vertigo, vomiting or slurred speech accompanies it, if half the face weakens on that side, if there is severe headache with fever and a stiff neck, if swelling and redness behind the ear push the outer ear forward, or if the perforation followed a head injury with clear fluid leaking. Do not put any drop into a discharging ear before a doctor has seen it. Keep it completely dry until the doctor tells you the drum has closed, because swimming with a perforated drum is a repeated cause of chronic infection that is hard to treat later.'
  },
  updated: '2026-09-08'
};

DX_BODY['menieres'] = {
  symptoms: {
    ar: 'نوبات لها ترتيب يكاد يكون ثابتاً: يسبقها بدقائق أو ساعات إحساس بامتلاء وضغط في أذن واحدة، ويشتدّ الطنين فيها ويصير أعمق، ويهبط السمع في تلك الأذن. ثم يهجم الدوار: العالم يدور دوراناً حقيقياً لا يستطيع معه المريض الوقوف، ويصحبه غثيان وقيء وتعرّق، ويستمرّ من عشرين دقيقة إلى ساعات، ثم ينحسر تاركاً إرهاقاً وعدم اتزان يستمرّ يوماً أو أكثر. والفارق بينه وبين دوار الوضعة أن نوبته أطول بكثير ولا تبدأ بحركة الرأس، وأنها تصحب أعراضاً سمعية دائماً. وبين النوبات قد يكون كل شيء طبيعياً في السنوات الأولى، ثم يستقرّ نقص السمع تدريجياً في تلك الأذن ويصير الطنين مقيماً، وتشتدّ الحساسية للأصوات العالية.',
    en: 'Attacks follow an almost fixed order: minutes or hours beforehand comes a feeling of fullness and pressure in one ear, the ringing in it grows louder and deeper, and hearing on that side drops. Then the vertigo strikes: the world truly spins so that the sufferer cannot stand, with nausea, vomiting and sweating, lasting from twenty minutes to several hours, then receding and leaving exhaustion and unsteadiness for a day or more. What separates it from positional vertigo is that its attack is far longer, does not begin with head movement, and is always accompanied by hearing symptoms. Between attacks everything may be normal in the early years, then the hearing loss in that ear settles gradually, the ringing becomes permanent, and sensitivity to loud sounds increases.'
  },
  cause: {
    ar: 'داخل الأذن الداخلية نظام من القنوات مملوء بسائل خاصّ محفوظ بتركيب وضغط دقيقين، فإذا زاد حجم هذا السائل أو ارتفع ضغطه انتفخ النظام وضغط على أغشيته، فاختلّ عمل خلايا التوازن والسمع معاً، وهذا هو التفسير الأشهر للمرض. ولماذا يزيد السائل عند شخص دون آخر فأمر غير محسوم: يُرجَّح خلل في تصريف السائل عبر كيس صغير في العظم، وقد يشارك فيه استعداد وراثي فبعض العائلات فيها أكثر من مصاب، أو تفاعل مناعي، أو أثر عدوى فيروسية قديمة، أو ضيق في تركيب العظم نفسه. وهناك محرّضات معروفة تزيد تكرار النوبات ولا تسبّب المرض: الإكثار من الملح، والكافيين، والتدخين، والكحول، وقلّة النوم، والتوتّر الشديد، وبعض أنواع الحساسية، وتغيّرات الضغط الجوي.',
    en: 'Inside the inner ear is a system of channels filled with a special fluid held at a precise composition and pressure, and if the volume or pressure of that fluid rises, the system swells and presses on its membranes, so the balance and hearing cells are disturbed together; this is the best-known explanation of the disease. Why the fluid increases in one person and not another is unsettled: a fault in the drainage of the fluid through a small sac in the bone is favoured, possibly with an inherited predisposition, since some families have more than one case, or an immune reaction, an old viral infection, or narrowness in the bone structure itself. There are known triggers that increase the frequency of attacks without causing the disease: excess salt, caffeine, smoking, alcohol, lack of sleep, severe stress, some allergies, and changes in atmospheric pressure.'
  },
  diagnosis: {
    ar: 'لا يوجد فحص واحد يثبت المرض، والتشخيص يُبنى على نمط النوبات مع دليل موضوعي على نقص السمع. لذلك يُطلب قياس السمع، ويُفضَّل إجراؤه أثناء نوبة أو قريباً منها، فيُظهر نقصاً يبدأ في الترددات المنخفضة وهو نمط مميّز يتذبذب من قياس إلى آخر في المراحل الأولى. وتُجرى فحوص التوازن التي تقيس استجابة كل أذن على حدة وتقارن بينهما، وفحص يقيس مرونة الطبلة، وفحص لردود الفعل العضلية الدهليزية. ويُطلب رنين مغناطيسي للدماغ والأذن بالصبغة، لا لإثبات المرض بل لاستبعاد ما يشبهه ويحتاج علاجاً مختلفاً تماماً: ورم على عصب السمع، وتصلّب متعدّد، وآفة في جذع الدماغ. وتُسحب تحاليل للغدة الدرقية والسكر والمناعة والزهري لأنها تحاكي الصورة أحياناً.',
    en: 'No single test proves the disease, and the diagnosis rests on the pattern of attacks together with objective evidence of hearing loss. Audiometry is therefore requested, preferably during or soon after an attack, showing a loss that begins in the low frequencies, a characteristic pattern that fluctuates from one test to the next in the early stages. Balance tests are performed that measure the response of each ear separately and compare them, along with a test of drum mobility and a test of vestibular muscle reflexes. Magnetic resonance imaging of the brain and ear with contrast is requested, not to prove the disease but to exclude what resembles it and needs entirely different treatment: a tumour on the hearing nerve, multiple sclerosis, or a lesion in the brainstem. Blood tests for thyroid, sugar, immunity and syphilis are taken, since these sometimes mimic the picture.'
  },
  treatment: {
    ar: 'العلاج يُبنى طبقات، ويُصعَّد فيه فقط إن فشل ما قبله. تبدأ الطبقة الأولى بضبط ما يُدخل الجسم: تقليل الملح تقليلاً حقيقياً وتوزيع السوائل على اليوم، وتقليل الكافيين والتدخين والكحول، وتنظيم النوم وتخفيف التوتّر — وهذا وحده يقلّل النوبات عند كثيرين. ويصف الطبيب دواءً يقلّل احتباس السوائل ودواءً يخفّف الدوار والغثيان أثناء النوبة فقط لا بشكل دائم. فإن استمرّت النوبات انتقل الأمر إلى حقن دواء داخل الأذن الوسطى في العيادة، ومنه ما يهدّئ الالتهاب ومنه ما يعطّل خلايا التوازن في تلك الأذن عمداً وتُوازن فائدته بخطره على السمع. وأخيراً خيارات جراحية تُخفّف الضغط أو تفصل عصب التوازن. ويبقى التأهيل الدهليزي بتمارين متدرّجة مفيداً جداً لعلاج عدم الاتزان الباقي بين النوبات، وكذلك المعين السمعي إن ثبت الفقد.',
    en: 'Treatment is built in layers and escalated only when the layer before it fails. The first controls what enters the body: a genuine reduction in salt with fluids spread through the day, less caffeine, smoking and alcohol, regular sleep and less stress, and this alone reduces attacks in many people. The doctor prescribes a medicine that reduces fluid retention and one that eases vertigo and nausea during an attack only, not permanently. If attacks persist, the next step is injecting medicine into the middle ear in the clinic; some of these calm inflammation while others deliberately disable the balance cells of that ear, with the benefit weighed against the risk to hearing. Finally there are surgical options that relieve the pressure or cut the balance nerve. Vestibular rehabilitation with graded exercises remains very useful for the unsteadiness that lingers between attacks, as does a hearing aid once the loss is established.'
  },
  seeDoctor: {
    ar: 'احجز عند طبيب أنف وأذن إن تكرّرت عندك نوبات دوار تدوم أكثر من عشرين دقيقة ويصحبها طنين أو امتلاء أو هبوط سمع في أذن واحدة، ولا تكتفِ بمسكّن دوار تشتريه كل مرّة، لأن التشخيص المبكر يحمي السمع. واذهب إلى الطوارئ فوراً إن جاء الدوار لأول مرّة في حياتك واستمرّ ساعات، أو صحبه أيّ من هذه: صداع شديد جديد، ازدواج رؤية، تلعثم أو صعوبة بلع، ضعف أو تنميل في وجه أو طرف، عدم قدرة على المشي إطلاقاً حتى بمساعدة، أو هبوط سمع مفاجئ. فهذي علامات تفرّق بين مشكلة في الأذن ومشكلة في الدماغ. وراجع سريعاً أيضاً إن تغيّر نمط نوباتك المعتاد أو صارت أطول أو أصابت الأذن الأخرى. وأثناء النوبة: استلقِ في مكان آمن وثبّت نظرك على نقطة ثابتة ولا تقُد سيارة.',
    en: 'Book with an ear, nose and throat doctor if you have repeated vertigo attacks lasting more than twenty minutes accompanied by ringing, fullness or reduced hearing in one ear, and do not settle for buying an anti-vertigo tablet each time, because early diagnosis protects hearing. Go to the emergency department at once if vertigo comes for the first time in your life and lasts hours, or if any of these accompany it: a severe new headache, double vision, slurred speech or difficulty swallowing, weakness or numbness of a face or limb, complete inability to walk even with help, or sudden hearing loss. These are the signs that separate an ear problem from a brain problem. Seek review quickly too if your usual attack pattern changes, if attacks lengthen, or if the other ear becomes involved. During an attack: lie down somewhere safe, fix your gaze on a still point, and do not drive.'
  },
  updated: '2026-09-08'
};

DX_BODY['vestibular-neuritis'] = {
  symptoms: {
    ar: 'يبدأ فجأةً وبقوّة: دوار دوراني شديد لا ينقطع، يجعل صاحبه يستلقي ويرفض أي حركة لأن كل التفاتة تضاعفه، ومعه غثيان وقيء متكرّر وتعرّق وشحوب، وعدم قدرة على المشي في مستقيم بل ميل ثابت إلى جهة واحدة. وترتجف العينان اهتزازاً لا إرادياً يراه من ينظر إليه. ويستمرّ هذا الشكل الحادّ من ساعات إلى يوم أو يومين ثم يبدأ بالانحسار ببطء على مدى أيام. والعلامة المميّزة والمطمئنة في آن واحد: السمع سليم تماماً ولا طنين ولا امتلاء في الأذن — فإن هبط السمع فالتشخيص يتغيّر. وغالباً يسبقه بأيام أو أسابيع زكام أو نزلة فيروسية. وبعد الشفاء يبقى عند بعضهم إحساس بالترنّح عند الحركات السريعة أو في الأماكن المزدحمة أسابيع.',
    en: 'It begins suddenly and forcefully: severe, unbroken spinning vertigo that makes the sufferer lie down and refuse any movement, since every turn of the head doubles it, with nausea, repeated vomiting, sweating and pallor, and an inability to walk straight, with a fixed drift to one side. The eyes tremble with an involuntary flicker visible to anyone looking. This acute phase lasts from hours to a day or two, then slowly recedes over days. The distinguishing and simultaneously reassuring sign is that hearing is entirely normal, with no ringing and no fullness in the ear; if hearing drops, the diagnosis changes. It is often preceded by days or weeks by a cold or a viral illness. After recovery, some are left with a sense of swaying on quick movements or in crowded places for weeks.'
  },
  cause: {
    ar: 'يخرج من كل أذن داخلية عصب ينقل إلى الدماغ إشارات التوازن، وهو ينقسم إلى فرعين. وفي هذا المرض يلتهب هذا العصب أو أحد فرعيه فتتوقّف إشاراته أو تضطرب، فيصل إلى الدماغ خبران متعارضان: أذن تقول إن الرأس يدور وأذن تقول إنه ساكن، فيولّد الدماغ إحساس الدوران. والسبب المرجّح عدوى فيروسية، غالباً من عائلة فيروسات كامنة في العقد العصبية تنشط مرّة، أو التهاب تالٍ لعدوى الجهاز التنفّسي العلوي، ولهذا يكثر بعد نزلات البرد وفي مواسمها. وقد يشترك فيه اضطراب في التروية الدقيقة للعصب عند من عنده عوامل خطر وعائية. وإن امتدّ الالتهاب ليشمل القوقعة معه هبط السمع وصار الاسم مختلفاً والتعامل أعجل، ولهذا يُسأل عن السمع دائماً.',
    en: 'From each inner ear runs a nerve carrying balance signals to the brain, and it divides into two branches. In this illness that nerve, or one of its branches, becomes inflamed so its signals stop or become disordered, and two contradictory reports reach the brain: one ear saying the head is spinning and the other that it is still, so the brain generates the sensation of spinning. The favoured cause is a viral infection, often from a family of viruses that lie dormant in nerve ganglia and reactivate once, or inflammation following an upper respiratory infection, which is why it is common after colds and in their season. A disturbance in the fine blood supply of the nerve may share in it in those with vascular risk factors. If the inflammation extends to include the cochlea, hearing drops, the name changes and the response must be faster, which is why hearing is always asked about.'
  },
  diagnosis: {
    ar: 'التشخيص سريري في المقام الأول، وأهمّ ما فيه هو التفريق بين دوار من الأذن ودوار من الدماغ، ويُعمل ذلك بمجموعة فحوص عند السرير: يلاحظ الطبيب اتجاه اهتزاز العينين وثباته وهل يتغيّر مع تغيّر اتجاه النظر، ويحرّك رأس المريض حركة سريعة قصيرة ويراقب كيف تلحق العين بالهدف فهذا يكشف ضعف عصب التوازن في جهة واحدة، ويفحص محاذاة العينين. ويفحص الأعصاب والمشي والاتزان بحثاً عن أي علامة تشير إلى الدماغ. ويُقاس السمع لأن سلامته شرط في التشخيص. ولا يُطلب تصوير في الحالة النموذجية عند شابّ بلا عوامل خطر، أمّا إن كان المريض كبيراً أو عنده ضغط وسكري وتدخين، أو ظهرت علامة عصبية واحدة، أو لم يستطع المشي إطلاقاً، فيُطلب رنين مغناطيسي للدماغ لاستبعاد سكتة في المخيخ أو جذع الدماغ.',
    en: 'The diagnosis is primarily clinical, and its most important part is separating vertigo of the ear from vertigo of the brain, done through a group of bedside tests: the doctor notes the direction of the eye flicker, whether it is fixed, and whether it changes with the direction of gaze; moves the patient head in a short rapid thrust and watches how the eye catches the target, which reveals weakness of the balance nerve on one side; and checks the alignment of the eyes. The nerves, gait and balance are examined for any sign pointing to the brain. Hearing is measured, since its being normal is part of the diagnosis. Imaging is not requested in a typical case in a young person without risk factors; but if the patient is older or has high blood pressure, diabetes or smokes, if a single neurological sign appears, or if he cannot walk at all, magnetic resonance imaging of the brain is requested to exclude a stroke in the cerebellum or brainstem.'
  },
  treatment: {
    ar: 'في اليوم الأول أو اليومين يكون الهدف احتمال الأعراض: راحة في مكان هادئ، وسوائل بكميات صغيرة متكرّرة لتعويض القيء، ودواء يخفّف الدوار والغثيان يصفه الطبيب لأيام قليلة فقط. والتحذير المهمّ هنا أن هذي الأدوية لا تُستعمل طويلاً، لأنها تعطّل الآلية التي يعوّض بها الدماغ نفسه فيطول التعافي بدل أن يقصر. وقد يصف الطبيب مضادّ التهاب قوياً في الأيام الأولى في حالات مختارة. وحجر الزاوية في العلاج هو التأهيل الدهليزي: تمارين متدرّجة لحركة العين والرأس والاتزان تبدأ مبكراً بمجرّد أن يهدأ القيء، وتُزعج في البداية عمداً لأن الانزعاج نفسه هو ما يدرّب الدماغ على إعادة المعايرة. والحركة أفضل من السرير: البقاء ساكناً أسابيع يؤخّر الشفاء. وأكثر المرضى يتعافون تماماً خلال أسابيع إلى شهرين.',
    en: 'In the first day or two the aim is to make the symptoms bearable: rest in a quiet place, small frequent drinks to replace what vomiting takes, and a medicine prescribed for a few days only that eases vertigo and nausea. The important warning here is that these medicines are not used for long, because they suppress the very mechanism by which the brain compensates, so recovery lengthens instead of shortening. A strong anti-inflammatory may be prescribed in the first days in selected cases. The cornerstone of treatment is vestibular rehabilitation: graded exercises for eye, head and balance movement begun early, as soon as the vomiting settles, and deliberately uncomfortable at first, because that discomfort is exactly what trains the brain to recalibrate. Movement is better than bed: staying still for weeks delays recovery. Most patients recover completely within weeks to two months.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً إذا جاءك دوار شديد مفاجئ لأول مرّة مع أيّ من هذه: صداع شديد جديد، تلعثم في الكلام أو صعوبة بلع، ازدواج رؤية أو فقدان جزء من البصر، ضعف أو تنميل في وجه أو ذراع أو ساق، عدم قدرة على الجلوس أو المشي إطلاقاً ولو بمساعدة، أو هبوط سمع مفاجئ أو طنين جديد. فالسكتة في المخيخ قد تبدو دواراً بسيطاً وهذي العلامات هي الفارق. وراجع الطبيب خلال يوم أو يومين إن استمرّ الدوار أكثر من يومين بلا تحسّن، أو تكرّر القيء حتى منع الشرب، أو كنت مصاباً بالسكري أو الضغط أو فوق الستين. وبعد التشخيص: لا تقُد سيارة ولا تعمل على سلّم أو آلة حتى يزول الدوار تماماً، وابدأ تمارين التأهيل ولا تلزم السرير أسابيع، واستشر طبيبك قبل أن تستمرّ على دواء الدوار أكثر من أيام.',
    en: 'Call an ambulance at once if severe vertigo strikes for the first time together with any of these: a severe new headache, slurred speech or difficulty swallowing, double vision or loss of part of the sight, weakness or numbness of a face, arm or leg, complete inability to sit or walk even with help, or sudden hearing loss or new ringing. A stroke in the cerebellum can look like simple vertigo, and these signs are the difference. See a doctor within a day or two if the vertigo lasts more than two days without improvement, if vomiting recurs until you cannot drink, or if you have diabetes or high blood pressure or are over sixty. After diagnosis: do not drive, or work on a ladder or machine, until the vertigo has fully gone; begin the rehabilitation exercises rather than staying in bed for weeks; and consult your doctor before continuing an anti-vertigo medicine beyond a few days.'
  },
  updated: '2026-09-08'
};

DX_BODY['presbycusis'] = {
  symptoms: {
    ar: 'الشكوى الأولى ليست ضعف السمع بل ضعف الفهم: تسمع أن أحدهم يتكلّم ولا تميّز ما يقول، وتطلب الإعادة كثيراً، وتشعر أن الناس صاروا يبلعون الحروف أو يهمسون. وتضيع الحروف الحادّة أولاً كالسين والشين والفاء والثاء، فتتشابه الكلمات ويختلّ المعنى. والمكان يفرق كثيراً: في غرفة هادئة تسمع جيداً، وفي مجلس فيه أصوات متداخلة أو مطعم أو حفلة تنقطع عنك المحادثة تماماً وتُرهقك محاولة اللحاق بها. وتُرفع الشاشة صوتاً حتى يشتكي أهل البيت، ويصعب سماع الهاتف وجرس الباب وصوت المرأة والطفل لأنهما أحدّ طبقة. ويصحبه طنين خفيف غالباً في الأذنين معاً. ويتقدّم ببطء شديد على سنوات، ولهذا يكون آخر من يلاحظه هو صاحبه.',
    en: 'The first complaint is not weak hearing but weak understanding: you hear someone speaking and cannot make out what he says, you ask for repetition often, and you feel that people have begun swallowing their letters or whispering. The high-pitched consonants go first, so words resemble each other and the meaning breaks down. The setting matters greatly: in a quiet room you hear well, while in a gathering of overlapping voices, a restaurant or a party the conversation is cut off from you entirely and the effort of keeping up exhausts you. The television is turned up until the household complains, and the telephone, the doorbell and the voices of women and children are hard to hear because they are higher in pitch. Mild ringing in both ears usually accompanies it. It advances very slowly over years, so the last person to notice it is its owner.'
  },
  cause: {
    ar: 'داخل القوقعة صفّ من خلايا شعرية دقيقة، كل جزء منها مخصّص لتردّد معيّن، وأشدّها إرهاقاً هي المسؤولة عن الأصوات الحادّة لأنها في مقدّمة الطريق وتتعرّض لكل صوت يدخل. وهذي الخلايا لا تتجدّد إذا تلفت، فما يُفقد منها لا يعود. ويتراكم عليها أثر العمر وأثر ما تعرّضت له من ضجيج طوال الحياة، ويضاف إلى ذلك ضعف التروية الدقيقة وتغيّرات في العصب السمعي وفي مراكز المعالجة داخل الدماغ، ولهذا يبقى فهم الكلام صعباً أحياناً حتى بعد رفع الصوت. وتزيد المشكلة عوامل معروفة: التعرّض المهني أو الترفيهي للضجيج العالي، والتدخين، والسكري، وارتفاع الضغط والدهون، وبعض الأدوية السامّة للأذن، والاستعداد العائلي. وسماع الموسيقى بصوت عالٍ في السمّاعات سنوات طويلة يُقدّم الموعد سنوات.',
    en: 'Inside the cochlea lies a row of fine hair cells, each part devoted to a particular frequency, and the most heavily worked are those responsible for high sounds, since they sit at the front of the road and meet every sound that enters. These cells do not regenerate once damaged, so what is lost of them does not return. Upon them accumulate the effect of age and the effect of all the noise met over a lifetime, joined by reduced fine blood supply and changes in the hearing nerve and in the processing centres inside the brain, which is why understanding speech sometimes stays difficult even after the volume is raised. Known factors worsen it: occupational or recreational exposure to loud noise, smoking, diabetes, high blood pressure and lipids, some medicines toxic to the ear, and family predisposition. Years of loud music through earphones bring the date forward by years.'
  },
  diagnosis: {
    ar: 'يبدأ الأمر بالنظر داخل الأذن لاستبعاد سبب بسيط قابل للعلاج كالشمع المنحشر أو سائل خلف الطبلة، فكثير ممن يظنّ سمعه شاخ إنما عنده سدادة شمع. ثم يُجرى قياس السمع في غرفة عازلة، وهو الفحص المعياري: يرسم منحنى لكل أذن على الترددات، وفي هذي الحالة يهبط المنحنى في الترددات العالية على الجانبين بشكل متماثل تقريباً. ويُضاف اختبار فهم الكلمات، وهو مهمّ جداً لأنه يقيس الفهم لا مجرّد السمع ويتنبّأ بمدى الاستفادة من المعين السمعي. ويُقاس ضغط الأذن الوسطى ومرونة الطبلة. والنقطة التي تستدعي مزيداً من الفحص هي عدم التماثل: أذن أضعف بوضوح من أختها، أو طنين في جانب واحد، فهذي تستوجب رنيناً مغناطيسياً لاستبعاد ورم على عصب السمع، لأن الشيخوخة تصيب الأذنين معاً.',
    en: 'It starts with looking inside the ear to exclude a simple treatable cause such as impacted wax or fluid behind the drum, since many who think their hearing has aged in fact have a wax plug. Audiometry in a sound-treated room follows, and it is the standard test: it plots a curve for each ear across the frequencies, and in this condition the curve falls in the high frequencies on both sides in a roughly symmetrical way. A word recognition test is added, and it matters greatly because it measures understanding rather than mere hearing and predicts how much benefit a hearing aid will give. Middle ear pressure and drum mobility are measured. The point that calls for further investigation is asymmetry: one ear clearly weaker than its fellow, or ringing on one side only, which requires magnetic resonance imaging to exclude a tumour on the hearing nerve, since ageing strikes both ears together.'
  },
  treatment: {
    ar: 'لا يوجد دواء يُرجع الخلايا التي فُقدت، والعلاج الحقيقي هو المعين السمعي، وهو اليوم صغير وذكيّ يفصل الكلام عن الضجيج ويُبرمَج على منحنى سمعك أنت بالذات. والخطأ الشائع أن يُشترى جهاز جاهز من متجر بلا قياس، فيرفع كل الأصوات معاً بما فيها الضجيج فيُترك في الدرج بعد أسبوع. والتبكير مهمّ: كلما طالت سنوات الحرمان صعب على الدماغ أن يستعيد مهارة فهم الكلام. ويحتاج الجهاز فترة تعوّد أسابيع وضبطاً متكرّراً، ولا يُحكم عليه من اليوم الأول. وإن كان الفقد شديداً جداً ولم ينفع المعين فزراعة القوقعة خيار مثبت حتى في كبار السنّ. ويكمله ما يُسمّى تدريب الاستماع، وترتيبات عملية: مواجهة المتكلّم، وإضاءة وجهه، وتقليل ضجيج الخلفية، وأجهزة تربط التلفاز والهاتف بالمعين مباشرة. وعلاج الضغط والسكري وترك التدخين يبطّئ التدهور.',
    en: 'There is no medicine that restores the cells that were lost, and the real treatment is a hearing aid, which today is small and intelligent, separating speech from noise and programmed to your own hearing curve. The common mistake is buying a ready-made device from a shop without measurement, so it raises all sounds together including the noise and is left in a drawer within a week. Acting early matters: the longer the years of deprivation, the harder it is for the brain to regain the skill of understanding speech. The device needs weeks of adjustment and repeated fine-tuning and must not be judged on the first day. If the loss is very severe and an aid does not help, cochlear implantation is a proven option even in older people. It is completed by what is called listening training and by practical arrangements: facing the speaker, lighting his face, reducing background noise, and devices that link the television and telephone directly to the aid. Treating blood pressure and diabetes and stopping smoking slow the decline.'
  },
  seeDoctor: {
    ar: 'احجز قياس سمع في موعد عادي إن صرت تطلب الإعادة كثيراً، أو ترفع صوت الشاشة أكثر من غيرك، أو تتجنّب المجالس والمطاعم لأنك لا تلحق الحديث، أو قال لك أهلك إنك لا تسمعهم — وصدّقهم فهم يلاحظون قبلك. ولا تؤجّل بحجّة أنه أمر طبيعي مع العمر، فالانتظار سنوات يُضعف نتيجة أي علاج ويرتبط بالعزلة وبتراجع الذاكرة والانتباه. واذهب في اليوم نفسه إن هبط سمع أذن واحدة فجأةً خلال ساعات أو أيام، فهذي حالة عاجلة مختلفة تماماً ونافذة علاجها قصيرة. وراجع سريعاً أيضاً إن كان الضعف في أذن واحدة بوضوح، أو معه طنين في جانب واحد، أو دوار، أو إفراز أو ألم، أو ضعف في نصف الوجه. ومن يعمل في ضجيج فالفحص الدوري وواقيات الأذن ليسا رفاهية.',
    en: 'Book a hearing test at an ordinary appointment if you have begun asking for repetition often, turn the screen up louder than others do, avoid gatherings and restaurants because you cannot follow the conversation, or your family tell you that you do not hear them; believe them, since they notice before you do. Do not put it off on the grounds that it is natural with age, because waiting years weakens the result of any treatment and is linked to isolation and to decline in memory and attention. Go the same day if the hearing of one ear drops suddenly over hours or days, because that is an entirely different, urgent condition with a short treatment window. Seek review quickly too if the loss is clearly in one ear, or comes with one-sided ringing, vertigo, discharge, pain, or weakness of half the face. For anyone working in noise, regular testing and ear protection are not a luxury.'
  },
  updated: '2026-09-08'
};

/* ==================== الشمّ والتذوّق ==================== */

DX_BODY['anosmia'] = {
  symptoms: {
    ar: 'الشكوى تبدأ غالباً من الطعام لا من الروائح: الأكل صار بلا نكهة، والقهوة ماء ساخن، والطبخة تحتاج ملحاً وبهاراً أكثر ولا تصل. ثم ينتبه صاحبها أنه لا يشمّ العطر ولا الطبخ ولا رائحة نفسه. وقد يكون النقص جزئياً فتُشمّ الروائح القوية وحدها، أو كاملاً فلا يصل شيء. وهناك صورة أشدّ إزعاجاً من الفقد نفسه: أن تنقلب الرائحة فيصير الطعام والعطر والدخان كلها رائحة واحدة كريهة أو محروقة أو معدنية، فيعاف صاحبها الأكل وينقص وزنه ويكتئب. وإن كان السبب انسداداً في الأنف فالشمّ يتذبذب: يرجع قليلاً حين ينفتح الأنف ويذهب حين يُسدّ. أمّا الخطر العملي الذي لا ينتبه له كثيرون فهو ذهاب نُذُر السلامة: تسرّب الغاز، والدخان، والطعام الفاسد.',
    en: 'The complaint usually starts with food rather than smells: meals have lost their flavour, coffee is hot water, and the cooking needs more salt and spice yet still does not arrive. Then the person notices that he cannot smell perfume, cooking, or himself. The loss may be partial, so that only strong smells get through, or complete, so that nothing does. There is a form more distressing than loss itself: smells turning, so that food, perfume and smoke all become one foul, burnt or metallic odour, so the sufferer loses appetite, loses weight and becomes low. If the cause is nasal blockage the sense fluctuates, returning a little when the nose opens and going when it closes. The practical danger many overlook is the loss of safety warnings: a gas leak, smoke, and spoiled food.'
  },
  cause: {
    ar: 'الشمّ يبدأ برقعة صغيرة من الخلايا العصبية في أعلى تجويف الأنف، ولا يصلها الهواء إلا إذا كان الطريق مفتوحاً، ثم تنقل الإشارة عبر عصب قصير إلى مقدّمة الدماغ. فالخلل إمّا في الطريق أو في الخلايا أو في العصب والدماغ. والسبب الأول والأشيع هو الانسداد: التهاب الأنف التحسّسي، والتهاب الجيوب المزمن، واللحميات الأنفية، وانحراف الحاجز، وهذي كلها قابلة للعلاج ويرجع الشمّ بعدها غالباً. والثاني عدوى فيروسية تصيب الخلايا نفسها، وقد يستمرّ الفقد أسابيع أو أشهراً ويتحسّن ببطء وقد يمرّ بمرحلة انقلاب الروائح أثناء التعافي. والثالث إصابة الرأس التي تقطع الألياف الرقيقة عند قاعدة الجمجمة. ثم أسباب أبطأ: التقدّم في العمر، والتدخين، وأمراض عصبية كباركنسون وألزهايمر يظهر فيها ضعف الشمّ مبكراً جداً، وبعض الأدوية، وأورام قاعدة الجمجمة، ونقص بعض الفيتامينات.',
    en: 'Smell begins at a small patch of nerve cells high in the nasal cavity, which air reaches only if the road is open, and the signal then travels through a short nerve to the front of the brain. The fault therefore lies in the road, in the cells, or in the nerve and brain. The first and commonest cause is blockage: allergic rhinitis, chronic sinus inflammation, nasal polyps and a deviated septum, all treatable, after which smell usually returns. The second is a viral infection striking the cells themselves; the loss may last weeks or months and improves slowly, sometimes passing through a phase of distorted smells during recovery. The third is head injury, which severs the fine fibres at the base of the skull. Then come slower causes: advancing age, smoking, neurological diseases such as Parkinson and Alzheimer in which weak smell appears very early, some medicines, tumours at the skull base, and deficiency of certain vitamins.'
  },
  diagnosis: {
    ar: 'يبدأ الطبيب بالتاريخ لأنه يفرّق بسرعة: هل بدأ الفقد فجأةً بعد نزلة أو ضربة، أم تدريجياً مع انسداد أنف مزمن، وهل يتذبذب مع فتح الأنف. ثم يُنظر داخل الأنف بمنظار رفيع، وهذي الخطوة أساسية لأنها ترى ما لا يُرى بالنظر العادي: لحميات صغيرة في أعلى الأنف، وتورّم الغشاء، وإفرازاً، وانحرافاً في الحاجز. ويُقاس الشمّ بفحص موضوعي بأعواد أو بطاقات ذات روائح معيارية يميّزها المريض، وهذا يحوّل شكوى ذاتية إلى رقم يُقارن لاحقاً بعد العلاج. وتُطلب أشعة مقطعية للجيوب إن اشتُبه في انسداد أو التهاب مزمن، ورنين مغناطيسي للدماغ إن كان الفقد بلا سبب واضح أو من جهة واحدة أو مع أعراض عصبية، لاستبعاد ورم أو إصابة في مسار الشمّ. وتُسحب تحاليل للسكر والدرقية وفيتامينات معيّنة عند الحاجة.',
    en: 'The doctor starts with the history, since it separates quickly: did the loss begin suddenly after a cold or a blow, or gradually with chronic nasal blockage, and does it fluctuate as the nose opens. The inside of the nose is then inspected with a fine endoscope, an essential step because it shows what ordinary looking cannot: small polyps high in the nose, swelling of the lining, discharge, and a deviated septum. Smell is measured objectively with standardised sticks or cards that the patient identifies, turning a subjective complaint into a figure that can be compared after treatment. A CT scan of the sinuses is requested if blockage or chronic inflammation is suspected, and magnetic resonance imaging of the brain if the loss has no clear cause, is one-sided, or comes with neurological symptoms, to exclude a tumour or injury along the smell pathway. Blood tests for sugar, thyroid and certain vitamins are taken where needed.'
  },
  treatment: {
    ar: 'العلاج يتبع السبب. فإن كان انسداداً فعلاجه يُرجع الشمّ غالباً: علاج الحساسية، وغسول ملحي للأنف يُستعمل بانتظام، وبخّاخ مضادّ للالتهاب يصفه الطبيب لمدّة كافية، وإزالة اللحميات أو تصحيح الحاجز جراحياً عند الحاجة. وإن كان الفقد بعد عدوى فيروسية فأهمّ ما ثبتت فائدته هو تدريب الشمّ: أن يشمّ المريض أربع روائح قوية مختلفة صباحاً ومساءً، كل واحدة نحو نصف دقيقة، وهو يستحضر ذكرى الرائحة، ويستمرّ على ذلك شهوراً لا أياماً، وتُغيَّر المجموعة كل فترة. وهذا التدريب رخيص وآمن ونتائجه حقيقية لكنه بطيء ويحتاج صبراً. وقد يضيف الطبيب علاجاً موضعياً في حالات مختارة. ومع كل حالة يُضاف تدبير السلامة: كاشف دخان يعمل في البيت، وكاشف غاز، والاعتماد على تواريخ الصلاحية بدل الشمّ، وحذر في التعامل مع مصادر الحريق.',
    en: 'Treatment follows the cause. If it is blockage, treating it usually restores smell: managing the allergy, regular saline rinsing of the nose, an anti-inflammatory spray prescribed by the doctor for a sufficient period, and removing polyps or correcting the septum surgically where needed. If the loss followed a viral infection, what has best proven its worth is smell training: the patient smells four different strong odours morning and evening, each for about half a minute, while recalling the memory of that smell, continuing for months rather than days, with the set changed periodically. This training is cheap, safe and genuinely effective, but slow and demanding of patience. The doctor may add a topical treatment in selected cases. Alongside every case go safety measures: a working smoke alarm at home, a gas detector, relying on expiry dates instead of smell, and caution around sources of fire.'
  },
  seeDoctor: {
    ar: 'راجع طبيب أنف وأذن في موعد قريب إن استمرّ ضعف الشمّ أكثر من أسبوعين بعد زوال الزكام، أو كان مصحوباً بانسداد أنف مزمن أو صداع في الوجه أو إفراز خلفي، أو بدأ تدريجياً بلا سبب. واذهب بسرعة أكبر إن كان الفقد في فتحة أنف واحدة فقط، أو معه نزيف أنف متكرّر من نفس الجهة، أو انسداد لا يفتح إطلاقاً، فهذه العلامات تستدعي نظرة داخل الأنف بالمنظار. واطلب الطوارئ إن فقدت الشمّ بعد ضربة على الرأس، أو صحبه صداع شديد جديد أو تغيّر في الرؤية أو ضعف أو تنميل أو تشوّش في الوعي أو نوبة تشنّج. وإن كنت كبير السنّ وضعف شمّك تدريجياً مع تغيّر في الحركة أو الذاكرة فاذكر ذلك لطبيبك صراحةً. وفي كل الأحوال: ركّب كاشف دخان وكاشف غاز في بيتك من اليوم.',
    en: 'See an ear, nose and throat doctor at an early appointment if weak smell persists more than two weeks after a cold has cleared, if it comes with chronic nasal blockage, facial headache or postnasal discharge, or if it began gradually without cause. Go more quickly if the loss is in one nostril only, if it comes with repeated nosebleeds from the same side, or with a blockage that never opens, since these call for an endoscopic look inside the nose. Seek emergency care if you lost your sense of smell after a blow to the head, or if a severe new headache, a change in vision, weakness, numbness, confusion or a seizure accompanies it. If you are older and your smell has weakened gradually alongside changes in movement or memory, tell your doctor plainly. In every case: fit a smoke alarm and a gas detector in your home today.'
  },
  updated: '2026-09-08'
};

DX_BODY['taste-disorder'] = {
  symptoms: {
    ar: 'الشكوى تُقال بثلاث صور. الأولى أن الطعم بهت أو غاب فصار الأكل واجباً ثقيلاً، ويميل صاحبه إلى الملح والسكّر والحارّ ليحسّ بشيء. والثانية أن الطعم انقلب: طعم معدني ثابت في الفم كأن قطعة نحاس تحت اللسان، أو مرارة لا تفارق، أو حلاوة زائفة، وتفسد كل أكلة حتى الماء. والثالثة إحساس بالحرق أو اللسع في اللسان والشفتين وسقف الحلق بلا أي تقرّح ظاهر، يخفّ أثناء الأكل ويشتدّ آخر النهار. ويصحب ذلك عادةً جفاف في الفم ولسان مغطّى أو أملس ورائحة فم. والملاحظة المهمّة أن أكثر من يشكو غياب الطعم إنما فقد الشمّ لا التذوّق، لأن ما نسمّيه نكهة يأتي معظمه من الرائحة الصاعدة إلى الأنف أثناء المضغ.',
    en: 'The complaint is put in three ways. First, that taste has faded or gone, so eating has become a heavy duty and the person reaches for salt, sugar and spice to feel something. Second, that taste has turned: a constant metallic taste as if a piece of copper lay under the tongue, or a bitterness that never leaves, or a false sweetness, spoiling every meal and even water. Third, a burning or stinging feeling in the tongue, lips and roof of the mouth with no visible ulcer, easing while eating and worsening at the end of the day. Dry mouth, a coated or smooth tongue and bad breath usually go with it. The important observation is that most people who complain of absent taste have in fact lost their sense of smell rather than taste, because what we call flavour comes mostly from the aroma rising into the nose during chewing.'
  },
  cause: {
    ar: 'اللسان يميّز أربع أو خمس صفات أساسية فقط، وكل تفاصيل النكهة تأتي من الشمّ. ولهذا فالسبب الأول لغياب الطعم هو خلل في الشمّ: زكام أو حساسية أو التهاب جيوب أو ما بعد عدوى فيروسية. والسبب الثاني هو الفم نفسه: جفاف اللعاب وهو أشيع مما يُظن لأن اللعاب هو الذي يذيب الطعام حتى تصل جزيئاته إلى براعم التذوّق، ثم التهاب اللثة وتسوّس الأسنان وأطقم الأسنان غير المضبوطة والقلاع الفطري وسوء نظافة الفم والتدخين. والسبب الثالث الأدوية، وهي سبب كبير يُغفل كثيراً: أصناف عديدة تغيّر الطعم أو تُحدث طعماً معدنياً، ولا يُوقَف أي دواء من تلقاء النفس بل يُراجَع الطبيب. ثم أسباب أخرى: نقص الحديد أو فيتامين ب اثني عشر أو الزنك، وقصور الدرقية، والسكري، والفشل الكلوي، والارتجاع المريئي، وعلاج الأورام والإشعاع على الرأس، وإصابات عصب الوجه أو اللسان بعد جراحة، وأمراض عصبية.',
    en: 'The tongue distinguishes only four or five basic qualities, and all the detail of flavour comes from smell. So the first cause of absent taste is a fault in smell: a cold, allergy, sinus inflammation or the aftermath of a viral infection. The second cause is the mouth itself: dryness of saliva, commoner than supposed because saliva is what dissolves food so its molecules reach the taste buds, then gum inflammation, tooth decay, ill-fitting dentures, oral thrush, poor mouth hygiene and smoking. The third cause is medicines, a large and often overlooked source: many classes alter taste or produce a metallic one, and no medicine is stopped on one own initiative but reviewed with the doctor. Then other causes: deficiency of iron, vitamin B twelve or zinc, an underactive thyroid, diabetes, kidney failure, acid reflux, cancer treatment and radiation to the head, injury to the facial or tongue nerve after surgery, and neurological disease.'
  },
  diagnosis: {
    ar: 'الخطوة الأولى فحص مباشر يفرّق بين التذوّق والشمّ: يُطلب من المريض أن يغلق أنفه ويتذوّق شيئاً حلواً ومالحاً وحامضاً ومرّاً، فإن ميّزها فالتذوّق سليم والمشكلة في الشمّ ويُوجَّه الفحص إلى الأنف. ثم يُفحص الفم بدقّة: اللسان وسطحه وبراعمه، واللثة والأسنان والأطقم، وعلامات الفطريات، ويُقاس تدفّق اللعاب إن اشتُكي من الجفاف. ويُراجَع كل دواء يتناوله المريض بلا استثناء مع تاريخ بدايته، لأن تزامن بدء الدواء مع بدء الشكوى هو أكثر ما يحسم. وتُسحب تحاليل دم: الحديد ومخزونه، وفيتامين ب اثني عشر، والزنك، ووظائف الدرقية والكلى، والسكر. وقد يُجرى فحص تذوّق كمّي في مراكز مختصّة. ويُطلب تصوير للدماغ إن صحب الاضطراب أعراض عصبية أو كان في نصف اللسان فقط.',
    en: 'The first step is a direct test separating taste from smell: the patient is asked to pinch the nose and taste something sweet, salty, sour and bitter, and if he distinguishes them, taste is intact and the problem is in smell, so the examination turns to the nose. The mouth is then examined carefully: the tongue, its surface and papillae, the gums, teeth and dentures, and signs of fungal infection, with saliva flow measured if dryness is reported. Every medicine the patient takes is reviewed without exception, along with the date it was started, because the coincidence of a medicine starting with the complaint starting is what most often settles the matter. Blood tests are taken: iron and its stores, vitamin B twelve, zinc, thyroid and kidney function, and sugar. Quantitative taste testing may be done in specialist centres. Brain imaging is requested if the disturbance comes with neurological symptoms or affects only one half of the tongue.'
  },
  treatment: {
    ar: 'العلاج يتّجه إلى السبب لا إلى العرض. فإن كان الشمّ فعلاجه هو الحلّ، وإن كان جفاف الفم فتُعالَج أسبابه ويُرطَّب بشرب الماء المتكرّر وبدائل اللعاب ومضغ ما يحفّز الإفراز، وتُصلَح الأسنان والأطقم وتُعالَج الفطريات، وتُضبط نظافة الفم واللسان يومياً. وإن كان دواءً فيناقش الطبيب تعديل الجرعة أو استبداله بغيره، ولا يُوقَف من تلقاء المريض أبداً. ويُصحَّح كل نقص يظهر في التحاليل بإشراف الطبيب، ويُضبط السكري وقصور الدرقية والارتجاع. أمّا الشكوى المستمرّة بلا سبب واضح فتُدار بالتدابير: تقوية النكهة بالأعشاب والحامض والملمس بدل الإفراط في الملح والسكّر، وتقديم الطعام بارداً أو بحرارة الغرفة لأن الروائح المزعجة تقلّ، وتجنّب الملاعق المعدنية إن كان الطعم معدنياً، والمضمضة قبل الأكل. ومتابعة الوزن ضرورة لأن فقد الشهيّة يقود إلى سوء تغذية بصمت.',
    en: 'Treatment addresses the cause, not the symptom. If it is smell, treating that is the answer; if it is dry mouth, its causes are treated and moisture restored by frequent drinking, saliva substitutes and chewing what stimulates secretion, while teeth and dentures are repaired, fungal infection treated, and daily mouth and tongue hygiene established. If it is a medicine, the doctor discusses adjusting the dose or replacing it, and it is never stopped by the patient alone. Every deficiency found on testing is corrected under the doctor supervision, and diabetes, an underactive thyroid and reflux are controlled. A persistent complaint with no clear cause is managed by measures: strengthening flavour with herbs, acidity and texture instead of excess salt and sugar; serving food cold or at room temperature, since unpleasant aromas are then weaker; avoiding metal spoons if the taste is metallic; and rinsing the mouth before eating. Watching the weight is essential, because loss of appetite leads silently to undernutrition.'
  },
  seeDoctor: {
    ar: 'راجع الطبيب في موعد عادي إن استمرّ تغيّر الطعم أكثر من أسابيع قليلة، أو بدأ مع دواء جديد، أو صحبه جفاف فم دائم، أو نقص وزنك لأنك لم تعد تشتهي الأكل. واذهب أبكر إن ظهرت في الفم أو اللسان قرحة لم تشفَ خلال أسبوعين، أو بقعة بيضاء أو حمراء ثابتة، أو كتلة أو تورّم، أو ألم عند البلع أو تغيّر في الصوت، أو خدر مستمرّ في اللسان أو الشفة، وبالأخصّ إن كنت مدخّناً — فهذي علامات لا تُترك للانتظار. واطلب الطوارئ إن جاء التغيّر فجأةً مع ضعف أو تنميل في نصف الوجه أو الجسم، أو تلعثم في الكلام، أو صعوبة في البلع، أو ميل في زاوية الفم. ولا تُوقف دواءً وصفه لك طبيبك بسبب الطعم من غير أن تكلّمه، فهناك دائماً بديل يُناقَش.',
    en: 'See a doctor at an ordinary appointment if a change in taste lasts more than a few weeks, if it began with a new medicine, if it comes with persistent dry mouth, or if you have lost weight because you no longer want to eat. Go sooner if an ulcer in the mouth or on the tongue has not healed within two weeks, if there is a fixed white or red patch, a lump or swelling, pain on swallowing or a change in the voice, or persistent numbness of the tongue or lip, and above all if you smoke, because these signs are not left to waiting. Seek emergency care if the change came suddenly with weakness or numbness of half the face or body, slurred speech, difficulty swallowing, or a drooping corner of the mouth. And do not stop a medicine your doctor prescribed because of the taste without speaking to him, since there is always an alternative to discuss.'
  },
  updated: '2026-09-08'
};
